import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"K-시스템(원작) 게임 메커니즘 레퍼런스","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Ref-K-System.md","filePath":"rules/Ref-K-System.md"}'),n={name:"rules/Ref-K-System.md"};function s(o,t,i,l,h,g){return e(),a("div",null,[...t[0]||(t[0]=[r(`<div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p></div><blockquote><p>출처 인계: <a href="https://github.com/islee23520/seoul-kenshi/blob/docs/reference-context-sync-st_01a079f1/.omo/research/README.md" target="_blank" rel="noreferrer">공유 조사 색인</a>. 로컬 sources.json·원문 패킷 언급은 조사 당시 기록이며 이 전달에 원시 자료가 포함된다는 뜻이 아니다. 누락된 ID는 미확인으로 남긴다. 자동 생성 문서입니다 — 원본은 저장소 내부 조사 문서(&quot;K-시스템 원본 조사 문서&quot;)에서 파생했으며 금지 용어는 위키 공개 기준에 맞게 치환했다.</p></blockquote><h1 id="k-시스템-원작-게임-메커니즘-레퍼런스" tabindex="-1">K-시스템(원작) 게임 메커니즘 레퍼런스 <a class="header-anchor" href="#k-시스템-원작-게임-메커니즘-레퍼런스" aria-label="Permalink to &quot;K-시스템(원작) 게임 메커니즘 레퍼런스&quot;">​</a></h1><ul><li>작성일: 2026-09-06. 대상: PC 기본 게임, 모드 제외. 일부 로컬 위키 항목은 1.0.68, 전투 해설은 1.0.65를 명시한다. 모든 수치를 동일 실행 파일에서 재검증한 문서는 아니다.</li><li><strong>[문서]</strong>: 읽은 공식 설명 또는 커뮤니티 위키에 명시된 사실. 커뮤니티 공식은 코드 검증이 아니라 문서화된 모델이다. <strong>[추론]</strong>: 그 사실을 연결한 설명·계산 예시. <strong>[미확인]</strong>: 자료 충돌, 엔진 세부 또는 이번 확인 범위 밖. 표의 표기는 표 전체에 적용하며 예외는 셀에 적는다.</li><li>출처 ID는 <code>.omo/evidence/gameplay-rubric-6d3fe97/ui-reference/sources.json</code>에 대응한다. <code>S-KEN-REF-*</code>는 이번에 읽은 자료를 등록한 ID다. 기존 구조 보고서의 사실을 재사용한 경우 이를 명시한다.</li><li>조사 제한: 지정 로컬 자료를 먼저 읽고 웹 API는 네 번만 요청했다. <code>Combat</code>, <code>Stats</code>는 <code>missingtitle</code>; 이미 존재하지 않는 것으로 확인된 <code>Research</code> 대신 <code>Technology</code>, 그리고 <code>World States</code>를 가져왔다. 부족한 세부는 기존 <code>내부 원문 덤프/</code> 덤프로 보충했다. CSS만 남은 원래 리뷰 덤프는 독립 근거로 사용하지 않았다. 직접 게임 실행·FCS 편집·바이너리 역공학은 하지 않았다. [문서: S-KEN-REF-01, S-KEN-REF-14]</li></ul><h2 id="_1-개요" tabindex="-1">1. 개요 <a class="header-anchor" href="#_1-개요" aria-label="Permalink to &quot;1. 개요&quot;">​</a></h2><p><strong>[문서] K-시스템는 Lo-Fi Games의 싱글플레이 분대 기반 오픈월드 RPG이자 생존·생산·전술 샌드박스다.</strong> Steam 출시일은 2018-12-06이며 공식 설명의 세계 면적은 870km² 이상이다. 상인, 도둑, 농부, 탐험가, 군벌, 노예 등은 고정 직업 선택지가 아니라 행동으로 만들어지는 역할이다. 선형 메인 스토리 대신 스스로 목표를 정하고, 인물의 신체·장비·기술·관계·소유 시설을 지속적으로 관리한다. [S-KEN-REF-02]</p><p><strong>[문서] 세계가 플레이어의 레벨에 맞추어 약해지거나 강해지지 않는다.</strong> 상점의 장비도 플레이어 수준으로 제한되지 않는다. 시작부터 대부분의 경비와 강적은 초보보다 강하며, 주인공만의 HP·영웅 보정은 없다. 전투·이동·노동은 같은 세계에서 이어지고, 패배한 인물이 살아 있으면 구출·회복·탈옥이 가능하다. [S-KEN-REF-02, S-KEN-REF-01]</p><table tabindex="0"><thead><tr><th>핵심 단위</th><th>지속되는 상태 [문서]</th><th>플레이에서의 의미 [추론]</th></tr></thead><tbody><tr><td>인물</td><td>부위별 건강, 혈액/기름, 허기, 기술, 장비, 범죄·노예 신분</td><td>돈이 있어도 운반자·치료자·건강한 다리를 잃으면 원정이 멈춤</td></tr><tr><td>분대·플레이어 세력</td><td>직접 조종 동료, 공유 자금, 세력 관계, 작업 분담</td><td>한 명이 쓰러져도 다른 한 명이 회복 경로를 유지할 수 있음</td></tr><tr><td>시설·연구</td><td>소유 건물, 설비, 재고, 연구 해금</td><td>전투 레벨과 독립적인 생산 역량의 성장</td></tr><tr><td>지역·세계</td><td>지형·기후·순찰, 중요 인물 상태, 도시 교체</td><td>길과 시장의 안전은 전투력 외 정치·환경에도 좌우됨</td></tr></tbody></table><p>위 표의 문서 근거: S-KEN-REF-01, S-KEN-REF-02, S-KEN-REF-03, S-KEN-REF-07, S-KEN-REF-10, S-KEN-REF-14.</p><p><strong>[추론] 플레이어의 실체는 처음부터 &#39;땅 없는 집단&#39;이지, 정착 후에야 생성되는 국가가 아니다.</strong> 모든 직접 조종 인물은 Nameless라는 플레이어 세력에 속하며 세력명을 바꿀 수 있다. 야외 기지는 선택 자산이다. 모든 도시를 정복하거나 정착해야만 끝나는 고정 승리 루프로 이해하면 실제 게임을 놓친다. [문서 근거: S-KEN-REF-01, S-KEN-REF-03]</p><h2 id="_2-코어루프" tabindex="-1">2. 코어루프 <a class="header-anchor" href="#_2-코어루프" aria-label="Permalink to &quot;2. 코어루프&quot;">​</a></h2><h3 id="_2-1-최소-생존-루프" tabindex="-1">2.1 최소 생존 루프 <a class="header-anchor" href="#_2-1-최소-생존-루프" aria-label="Permalink to &quot;2.1 최소 생존 루프&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[추론: S-KEN-REF-01, S-KEN-REF-07, S-KEN-REF-08]</span></span>
<span class="line"><span>안전한 시장/은신처 확인</span></span>
<span class="line"><span>  -&gt; 식량·의약품 확보</span></span>
<span class="line"><span>  -&gt; 채광·약탈·교역·현상금·탐험 중 감당 가능한 작업 선택</span></span>
<span class="line"><span>  -&gt; 이동/노동/전투로 기술 경험 + 돈/장비/지식 물품 획득</span></span>
<span class="line"><span>  -&gt; 부상자 구조·출혈 처치·휴식·판매</span></span>
<span class="line"><span>  -&gt; 다음 원정의 거리/위험/인원을 늘리거나 손실을 복구</span></span></code></pre></div><p><strong>[문서] 초반부터 가능한 경로는 경비가 쓰러뜨린 적의 약탈, 경비와 함께 전투, 구리·철 채굴 판매, 교역, 은신·절도, 음식 조리 등이다.</strong> 적을 직접 죽여야만 성장하거나 전리품을 얻는 것은 아니다. 전투 밖에 구조자 한 명을 남겨 두면 패배 후 부상자를 업고 치료할 수 있다. [S-KEN-REF-01]</p><p><strong>[추론] 이 루프에서 중요한 것은 승률만이 아니라 실패의 회수 가능성이다.</strong> 상대가 음식만 훔치는지, 사슬을 채우는지, 살아 있는 몸을 먹는지에 따라 같은 전투 패배의 비용이 달라진다. 전투 기술을 키우겠다고 포식자에게 쓰러지는 것과 경비 근처에서 도적에게 맞는 것은 동일한 훈련이 아니다. [문서 근거: S-KEN-REF-04, S-KEN-REF-06, S-KEN-REF-07]</p><h3 id="_2-2-정착지의-생산-루프" tabindex="-1">2.2 정착지의 생산 루프 <a class="header-anchor" href="#_2-2-정착지의-생산-루프" aria-label="Permalink to &quot;2.2 정착지의 생산 루프&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[추론: S-KEN-REF-10, S-KEN-REF-13]</span></span>
<span class="line"><span>원료 확보 -&gt; 가공 -&gt; 전용 저장 -&gt; 제작/요리 -&gt; 소비·건설·판매</span></span>
<span class="line"><span>   ^                                            |</span></span>
<span class="line"><span>   +-- 연구·설비·작업 숙련·운반 개선에 재투자 ----+</span></span>
<span class="line"><span></span></span>
<span class="line"><span>추가 입력: 노동자 + 물 + 전력 + 조명 + 방어/정치적 접근성</span></span></code></pre></div><p><strong>[문서] Jobs는 위에서 아래로 실행 가능한 작업을 찾는 우선순위 명령 목록이다.</strong> Shift+우클릭으로 등록하고 드래그로 순서를 바꾼다. 상위 작업이 다시 가능해지면 하위 작업을 중단할 수 있다. 생산, Auto-Haul, 시체 처리, 동물 약탈, 의료·수리 등을 맡길 수 있다. Medic·Turret처럼 별도 우선 동작이 있는 작업도 있다. 특히 Medic/Robotics는 Jobs 토글을 꺼도 남아 작동할 수 있어 중단하려면 작업 자체를 제거해야 한다. [S-KEN-REF-13]</p><p><strong>[추론] &#39;자동화 설비의 작업자 0명&#39;과 &#39;물류 인원 0명&#39;은 다르다.</strong> 원료 운반·완제품 반출·저장 공간·전력 부족 중 하나가 막히면 산업은 멈춘다. 의료 자동 작업은 죽은 척하던 인물을 일으켜 적에게 노출시킬 수도 있으므로 편의 기능과 생존 판단을 함께 관리해야 한다. [문서 근거: S-KEN-REF-07, S-KEN-REF-10, S-KEN-REF-13]</p><h3 id="_2-3-식량이-정하는-활동-시간" tabindex="-1">2.3 식량이 정하는 활동 시간 <a class="header-anchor" href="#_2-3-식량이-정하는-활동-시간" aria-label="Permalink to &quot;2.3 식량이 정하는 활동 시간&quot;">​</a></h3><p><strong>[문서] 일반 인물의 허기 막대는 최대 300이고, 음식 1Nu는 허기 1을 회복한다.</strong> 음식은 한 번에 순간 회복이 아니라 먹는 동안 차오른다. 보통 250 미만에서 자동 섭취하며, 먹을 수 있는 재료만 있으면 200 미만까지 기다린다. 한 번에 최대 50Nu를 소비할 수 있어 125Nu 식량도 여러 번 나누어 먹는다. 200 미만부터 영양실조가 발생한다. [S-KEN-REF-07, S-KEN-REF-08]</p><table tabindex="0"><thead><tr><th>종족</th><th style="text-align:right;">기본 허기 배율 [문서]</th><th>경제상 결과 [추론]</th></tr></thead><tbody><tr><td>Greenlander</td><td style="text-align:right;">1.00</td><td>비교 기준</td></tr><tr><td>Scorchlander</td><td style="text-align:right;">0.90</td><td>기준보다 적은 식비</td></tr><tr><td>Shek</td><td style="text-align:right;">1.25</td><td>인원을 늘릴 때 식량 수요가 큼</td></tr><tr><td>Hive Prince / Worker Drone</td><td style="text-align:right;">0.50 / 0.50</td><td>장거리 식량 적재에 유리</td></tr><tr><td>Hive Soldier Drone</td><td style="text-align:right;">0.60</td><td>Hiver 중에는 조금 더 먹음</td></tr><tr><td>Skeleton</td><td style="text-align:right;">0</td><td>식량 대신 수리품·수리침대 접근이 중요</td></tr></tbody></table><p>위 표의 근거: S-KEN-REF-07. 배율은 하루 고정 소비량이 아니다. 일·휴식·적재 등의 활동과 게임 설정이 실제 소모에 영향을 준다.</p><p><strong>[문서] 침대·야전 침상에서 자면 허기 소모는 일반 상태의 0.33배다. 음식은 부패하지 않으며 개인 생존용 식수는 필요하지 않다.</strong> 물은 농사·요리·생산 재료다. 근처 같은 분대의 착용 배낭에 식량을 넣으면 공유할 수 있고, 동물도 같은 분대의 배낭에서 먹을 수 있다. 다른 분대나 먼 지역에 있는 식량까지 전역 공유되는 창고로 해석하지 않는다. [S-KEN-REF-07, S-KEN-REF-08]</p><h2 id="_3-진행구조" tabindex="-1">3. 진행구조 <a class="header-anchor" href="#_3-진행구조" aria-label="Permalink to &quot;3. 진행구조&quot;">​</a></h2><h3 id="_3-1-기본-시작-13종-결핍-조합" tabindex="-1">3.1 기본 시작 13종: 결핍 조합 <a class="header-anchor" href="#_3-1-기본-시작-13종-결핍-조합" aria-label="Permalink to &quot;3.1 기본 시작 13종: 결핍 조합&quot;">​</a></h3><p><strong>[문서] 기본 Game Starts는 13종이다.</strong> 표시된 난이도는 시작 처지이며 RPG/Trading RPG/RTS 표기는 직업 잠금이 아니다. 아래 수치는 기존 구조 보고서가 전개해 읽은 Game Starts 자료를 재사용했다. 금액은 Cats(c), 괄호의 결핍 해석은 [추론]이다. 기본 관계는 모든 적대 세력과 평화라는 뜻이 아니다. [S-KEN-REF-01; 원 조사 S82]</p><table tabindex="0"><thead><tr><th>시작</th><th>장소·인원·현금</th><th>실제 강점·결핍과 특수 조건</th></tr></thead><tbody><tr><td>Wanderer</td><td>The Hub / 1명 / 1,000c</td><td>능력 1, Unknown급 Iron Club·Rag Loincloth, 비영양실조. 기본 관계·무현상금. 소개문의 &#39;녹슨 검&#39;과 장비 명세는 다름. (돈은 조금 있으나 전투·노동·구조자 부족)</td></tr><tr><td>The Wandering Trader</td><td>Trader&#39;s Edge / 1명+청소년 Pack Bull / 0c</td><td>Luxury Goods 5, Hacksaw 6, Gohan 2, Standard Kit 2, 상인·황소 배낭. 사람 능력 1, 황소 전투 약 25±3. Traders Guild +75. (현금은 없지만 매각 자산·수송력이 있음)</td></tr><tr><td>The Holy Sword</td><td>The Hub / 1명 / 100c</td><td>Edge 1-3 Nodachi·옷·응급키트, 기본 능력 1에 변동. HN -100, 미사용 세력 Imperial Lords -100; HN/UC 현상금 20,000c 표기. UC 관계 -100으로 바꾸어 읽지 않음. (좋은 무기지만 숙련·합법 시장 부족)</td></tr><tr><td>The Cannibal Hunters</td><td>Cannibal Village / 2명 / 9c</td><td>전투 5인 인물과 전투 2·도둑 계열 20인 인물, 응급키트와 부목. 곧바로 공격받음. 전체 무기·방어구 세트는 미확인. (구조자는 있으나 시작부터 탈출해야 함)</td></tr><tr><td>The Hive Exile</td><td>Hive Village / Hiver 1명 / 0c</td><td>능력 1, 장비·식량 없음, 비영양실조. Western Hive Prince/Soldier/Worker만 선택; Hiveless 거래 제약. (종족 생존 효율은 있으나 자본·시장 접근 부족)</td></tr><tr><td>Son of a Captain</td><td>The Hub / 1명 / 0c</td><td>Catun 1-3 Katana, Leather Shirt·Samurai Clothpants·Drifter&#39;s Boots, Gohan·응급키트. UC +100, HN -100. 실제 Malnourished=False. (장비·후원과 종교국 적대를 교환)</td></tr><tr><td>The Slaves</td><td>Rebirth / 기본 2명 / 0c</td><td>능력 1, 노예복·잠긴 족쇄, 허기 170/300. Skeleton 불가, 인원은 Squad Size Multiplier 영향. 초기 현상금과 별도로 노예 신분. (생계 자율성·이동 자유 부족)</td></tr><tr><td>Rock Bottom</td><td>Sho-Battai 동쪽 Great Desert / 1명 / 0c</td><td>무장·의복 없음, 왼팔 없음, 능력 1, 허기 170. (빈곤+영양실조+신체 결손+사막 포획 위험)</td></tr><tr><td>Empire Citizen</td><td>Sho-Battai / 1명 / 750c</td><td>능력 1, Rag Shirt·ragged Halfpants·Wooden Sandals, 비영양실조. 기본 관계·무현상금. (도시 접근은 있으나 무장·숙련 부족)</td></tr><tr><td>Holy Nation Citizen</td><td>Bad Teeth 또는 Stack / 1명 / 200c</td><td>Human만 가능, HN +15, Iron Club·Stout Hessian·Cloth Shirt·Drifter&#39;s Boots, The Holy Flame. (종교적 접근성을 얻지만 선택 종족 제한)</td></tr><tr><td>Guy with a Dog</td><td>Bast / 1명+아기 Bonedog / 13c</td><td>Iron Stick·Rag Loincloth·Basic Kit, 영양실조. 개 기초 전투 약 20±5이나 아기 성장 배율로 매우 약함. (먹는 입·성장 대기·위험 지역 부담)</td></tr><tr><td>The Freedom Seekers</td><td>무작위 Waystation / 6명 / 4,000c</td><td>초보 5+전투 약 20-25 Old Soldier. 배낭 5, 건재 20, 철판 20, 천 4, 밀 10, Gohan 17, Basic Kit 9+Standard Kit 1. 밀농사 설계도, Storm House·밀 저장 연구. Old Soldier는 HN 현상금 20,000c. (생산 자본은 있으나 방어력이 보장되지 않음)</td></tr><tr><td>Nobodies</td><td>Hub 또는 Waystation Ruins 2곳 중 하나 / 5명 / 0c</td><td>전원 능력 1·Iron Stick·Cargopants, 개요상 Basic Kit 2, 허기 170. (노동력은 많지만 현금·식량·숙련 부족)</td></tr></tbody></table><p><strong>[추론] 시작의 난도는 <code>현금 + 처분 자산 + 노동력 - 먹는 입 - 부상 - 적대·불법 신분 - 탈출 부담</code>이라는 다축 조합이다.</strong> Trader의 0c와 Rock Bottom의 0c를 같은 무자본 시작으로 취급해서는 안 된다. &#39;Rebel&#39;은 플레이 역할이며 별도의 기본 시작으로 확인되지 않는다. [S-KEN-REF-01]</p><h3 id="_3-2-캠페인의-역량-단계" tabindex="-1">3.2 캠페인의 역량 단계 <a class="header-anchor" href="#_3-2-캠페인의-역량-단계" aria-label="Permalink to &quot;3.2 캠페인의 역량 단계&quot;">​</a></h3><table tabindex="0"><thead><tr><th>단계</th><th>일반적인 행동 [문서]</th><th>전환 기준 [추론]</th></tr></thead><tbody><tr><td>생존</td><td>도시 서비스, 식량·붕대, 도주·채광·잔해 약탈</td><td>한 번 패배해도 회복할 자원과 구조자를 확보</td></tr><tr><td>유랑 분대</td><td>동료 모집, 배낭·짐승, 지역 교역·현상금·유적 탐험</td><td>왕복 식량과 부상자 운반을 감당</td></tr><tr><td>전문화</td><td>근접·사수·도둑·의료·연구·제작 역할 분담</td><td>일부가 빠져도 전체 루프가 멈추지 않음</td></tr><tr><td>선택적 정착</td><td>도시 집 또는 야외 생산·방어망</td><td>생산 이득이 방어·물류·정치 부담보다 큼</td></tr><tr><td>후기 원정·정치</td><td>고대 연구품, 고급 장비, 지도자 포획·세계 상태 변화</td><td>강한 적과 반복 보복을 감당하거나 우회 가능</td></tr></tbody></table><p>근거: S-KEN-REF-01, S-KEN-REF-02, S-KEN-REF-10, S-KEN-REF-14. 이는 고정 장·해금일·권장 레벨 표가 아니다.</p><h3 id="_3-3-연구-6단계와-지식-물품" tabindex="-1">3.3 연구 6단계와 지식 물품 <a class="header-anchor" href="#_3-3-연구-6단계와-지식-물품" aria-label="Permalink to &quot;3.3 연구 6단계와 지식 물품&quot;">​</a></h3><p><strong>[문서] 연구는 Science 작업자, 연구대, 소모 지식 물품, 선행 기술, 시간이 함께 필요하다.</strong> 기술은 Core/Crafting/Defense/Electrics/Farming/Industry/Smithing/Training의 8계열, 6단계다. 설계도로 배우는 기술도 있다. 다음 표의 시간은 위키의 예상 시간이지 어떤 Science에서도 같은 완료 시간이라는 뜻이 아니다. 연구대 II 이상은 업그레이드 가능하며 여러 연구대는 속도를 더하지만 체감 수익이 있다. [S-KEN-REF-10, S-KEN-REF-14]</p><table tabindex="0"><thead><tr><th>도달 단계</th><th>단계 연구비·선행 조건 [문서]</th><th style="text-align:right;">예상 연구 시간</th><th>해당 연구대 신규 건설·전력·효율</th></tr></thead><tbody><tr><td>I</td><td>초기 단계</td><td style="text-align:right;">-</td><td>Small Research Bench: 건재 3; 초기 연구용</td></tr><tr><td>II</td><td>Small House 선행 + Book 6</td><td style="text-align:right;">4시간</td><td>Iron Plates 10 / 전력 0 / 90%</td></tr><tr><td>III</td><td>II + Book 10</td><td style="text-align:right;">10시간</td><td>Iron Plates 20 / 전력 10 / 95%</td></tr><tr><td>IV</td><td>III + Ancient Science Book 4</td><td style="text-align:right;">16시간</td><td>Iron Plates 25 / 전력 15 / 100%</td></tr><tr><td>V</td><td>IV + Ancient Science Book 8</td><td style="text-align:right;">24시간</td><td>Iron Plates 30 / 전력 25 / 105%</td></tr><tr><td>VI</td><td>V + AI Core 2</td><td style="text-align:right;">32시간</td><td>Iron Plates 35 / 전력 30 / 110%</td></tr></tbody></table><p>표 근거: S-KEN-REF-01, S-KEN-REF-10. Small House+Tech II의 Book 합계는 8이다. 단계 연구비는 개별 기술비를 포함하지 않으며, 연구대 표는 단계별 신규 건설 명세이지 업그레이드 때 항상 전액을 다시 낸다는 뜻이 아니다.</p><p><strong>[문서] Book은 일반 연구, Ancient Science Book·Engineering Research·AI Core는 고급 연구의 병목이다.</strong> 고대 유적 탐험은 연구 물품의 중요한 공급원이므로 생산 기지가 있어도 원정을 계속할 이유가 생긴다. Hydroponics는 V단계에서 AI Core 1, 6시간 예상의 기초 연구 뒤 작물별 연구가 필요하다. Hemp/Riceweed/Vegetables는 각각 Ancient Science Book 4, Wheatstraw는 2다. [S-KEN-REF-01, S-KEN-REF-10]</p><p><strong>[미확인] 이 문서는 개별 기술 전체의 FCS 의존 그래프를 재현한 것은 아니다.</strong> 단계 VI 도달이 모든 기술·모든 장비의 자동 해금을 뜻하지 않는다. 무기 제작은 연구·작업대·장인의 숙련이 함께 품질 상한을 결정한다. [S-KEN-REF-10, S-KEN-REF-12]</p><h2 id="_4-경제" tabindex="-1">4. 경제 <a class="header-anchor" href="#_4-경제" aria-label="Permalink to &quot;4. 경제&quot;">​</a></h2><h3 id="_4-1-유랑-경제-수입과-비용" tabindex="-1">4.1 유랑 경제: 수입과 비용 <a class="header-anchor" href="#_4-1-유랑-경제-수입과-비용" aria-label="Permalink to &quot;4.1 유랑 경제: 수입과 비용&quot;">​</a></h3><p><strong>[문서] 통화는 Cats다.</strong> 직접 조종 정식 동료는 보통 한 번의 가입비를 내며 일반적인 범위는 3,000-7,500c다. 무료 특수 동료·해방 후 합류·동물 구매도 있다. 매일 전원에게 임금을 주는 용병회사 경제가 아니며, 기간제 NPC 경호 계약은 별도다. 자료 간 경호 단가가 달라 보편적인 일당을 확정하지 않는다. [S-KEN-REF-01]</p><table tabindex="0"><thead><tr><th>수입원</th><th>필요한 것 [문서]</th><th>수익을 깎는 비용 [추론]</th></tr></thead><tbody><tr><td>광석 판매</td><td>광맥, Labouring, 시장·운반</td><td>왕복 시간·적재로 느려진 도주</td></tr><tr><td>전투 후 약탈</td><td>쓰러진 대상, 안전한 수거</td><td>물건의 소유권·적대·공간·무게</td></tr><tr><td>교역</td><td>매입 자본, 지역 가격차, 배낭/짐승</td><td>식량·경호·위험 경로·매각처 접근</td></tr><tr><td>절도·밀수</td><td>Stealth, Thievery, Lockpicking, 판로</td><td>현상금·구금·장물 할인·시장 적대</td></tr><tr><td>현상금</td><td>대상 식별, 제압, 치료·운반, 발행 세력</td><td>생포 부담·구조 위험·정치적 반대편</td></tr><tr><td>제작·농업</td><td>연구·설비·노동·원료</td><td>초기 투자·회수 시간·재고·전력·습격</td></tr></tbody></table><p>근거: S-KEN-REF-01, S-KEN-REF-05, S-KEN-REF-10, S-KEN-REF-12.</p><p><strong>[문서] 장물은 다른 세력·Hive·Shinobi Thieves에 팔 때 판정상 성공률 100%이며, 원 소유 세력에 되팔기 성공률은 <code>20 + 0.42 × Thievery</code>%로 설명된다.</strong> 대부분 장물은 정상 판매 가치의 절반이다. 이를 무조건 안전한 운송·입점 보장으로 읽으면 안 된다. [S-KEN-REF-12]</p><p><strong>[추론] 유랑의 실질 운영 자본은 현금뿐 아니라 음식·수리품·건강·합법 판로·운반력이다.</strong> <code>매각 수입 - 매입비 - 음식/의약/탄약 - 경호/숙박 - 손실 복구</code>가 재투자 여력이다. 정식 동료의 급료 항을 다른 게임에서 가져와 임의로 더하지 않는다. [문서 근거: S-KEN-REF-01, S-KEN-REF-08]</p><h3 id="_4-2-음식-가치와-조리" tabindex="-1">4.2 음식 가치와 조리 <a class="header-anchor" href="#_4-2-음식-가치와-조리" aria-label="Permalink to &quot;4.2 음식 가치와 조리&quot;">​</a></h3><p><strong>[문서] 아래는 지역 가격 변동 전 기본값이다.</strong> 실제 상점 가격은 달라질 수 있다. Nu/슬롯과 c/Nu는 서로 다른 효율이며, 비싼 압축 식량은 긴 원정에 가치가 있다. [S-KEN-REF-08]</p><table tabindex="0"><thead><tr><th>음식</th><th style="text-align:right;">영양 Nu</th><th style="text-align:right;">기본 매입/매각 c</th><th>무게 kg / 공간 슬롯</th><th>비고</th></tr></thead><tbody><tr><td>Dried Meat</td><td style="text-align:right;">15</td><td style="text-align:right;">78 / 39</td><td>1 / 4</td><td>생고기 조리, 값싼 초기 음식</td></tr><tr><td>Chewsticks</td><td style="text-align:right;">20</td><td style="text-align:right;">152 / 76</td><td>0.5 / 6</td><td>선인장 계열</td></tr><tr><td>Cooked Vegetables</td><td style="text-align:right;">25</td><td style="text-align:right;">318 / 159</td><td>1 / 9</td><td>채소 조리</td></tr><tr><td>Rice Bowl</td><td style="text-align:right;">25</td><td style="text-align:right;">186 / 93</td><td>1 / 9</td><td>쌀 조리</td></tr><tr><td>Bread</td><td style="text-align:right;">30</td><td style="text-align:right;">488 / 244</td><td>0.5 / 6</td><td>식용 재료이기도 함; 200 미만 섭취 규칙 주의</td></tr><tr><td>Meatwrap</td><td style="text-align:right;">50</td><td style="text-align:right;">658 / 329</td><td>1 / 6</td><td>고기+빵 계열</td></tr><tr><td>Dustwich</td><td style="text-align:right;">70</td><td style="text-align:right;">730 / 365</td><td>1 / 6</td><td>선인장+빵 계열</td></tr><tr><td>Foodcube</td><td style="text-align:right;">75</td><td style="text-align:right;">874 / 437</td><td>1 / 6</td><td>채소+빵 계열</td></tr><tr><td>Gohan</td><td style="text-align:right;">75</td><td style="text-align:right;">444 / 222</td><td>1 / 9</td><td>채소+쌀 계열</td></tr><tr><td>Ration Pack</td><td style="text-align:right;">125</td><td style="text-align:right;">1,143 / 571</td><td>1 / 4</td><td>기본 게임에서 플레이어 제작 불가</td></tr><tr><td>Ancient Nutri-Rations</td><td style="text-align:right;">125</td><td style="text-align:right;">1,143 / 571</td><td>1 / 4</td><td>탐험 식량</td></tr><tr><td>Raw Meat</td><td style="text-align:right;">15</td><td style="text-align:right;">60 / 30</td><td>1 / 4</td><td>동물·Hiver·Scorchlander가 생식 가능</td></tr><tr><td>Foul Raw Meat</td><td style="text-align:right;">10</td><td style="text-align:right;">1 / 0</td><td>1 / 4</td><td>동물·Hive Worker/Soldier용, Prince는 제외</td></tr></tbody></table><p><strong>[추론] Gohan은 기본값에서 444/75=5.92c/Nu, Dried Meat는 5.20c/Nu지만, Ration Pack은 31.25Nu/슬롯으로 두 음식보다 적재 효율이 높다.</strong> 장거리 탐험·상단은 최저 식비와 최고 공간 효율 중 무엇이 병목인지 판단한다. Greenfruit·Riceweed·Wheatstraw 자체는 먹을 수 없으므로 수확했다고 즉시 식량이 확보된 것은 아니다. [문서 근거 및 계산: S-KEN-REF-08]</p><h3 id="_4-3-정착의-세-상태와-건축" tabindex="-1">4.3 정착의 세 상태와 건축 <a class="header-anchor" href="#_4-3-정착의-세-상태와-건축" aria-label="Permalink to &quot;4.3 정착의 세 상태와 건축&quot;">​</a></h3><table tabindex="0"><thead><tr><th>상태</th><th>시설·서비스 [문서]</th><th>경계</th></tr></thead><tbody><tr><td>유랑+Camping</td><td>야전 침상·취사·쉼터</td><td>Camping은 플레이어 도시를 만들지 않아 도시 방문 이벤트 표적이 되지 않지만 주변 적은 여전히 위험</td></tr><tr><td>NPC 도시의 소유 건물</td><td>구매·폐허 수리, 연구·저장·제작, 경비 보호</td><td>도시 자체의 소유권 아님. 대형 실외 설비 제한</td></tr><tr><td>야외 Outpost</td><td>농사·광업·발전·산업·성벽·포탑</td><td>세금·조공·기도·습격·물류·수비 분담을 추가로 부담</td></tr></tbody></table><p>근거: S-KEN-REF-01. Town Override 때 소유 자산 보존 여부는 자료가 충돌하므로 7.3과 10.4 참조.</p><p><strong>[문서] Small Shack은 연구 없이 건재 5개, Storm House는 Small House 연구 뒤 건재 16개로 짓는다.</strong> Small Shack은 Small Research Bench용이며 큰 연구대 배치를 위해 더 큰 건물이 필요하다. Storm House 옥상에는 소형 풍력·집수·포탑 같은 설비를 둘 수 있다. 소유 건물과 설비는 Engineer가 건설·수리한다. [S-KEN-REF-10, S-KEN-REF-13]</p><h3 id="_4-4-산업·전력망" tabindex="-1">4.4 산업·전력망 <a class="header-anchor" href="#_4-4-산업·전력망" aria-label="Permalink to &quot;4.4 산업·전력망&quot;">​</a></h3><table tabindex="0"><thead><tr><th>생산 사슬</th><th>문서화된 입력/출력·설비 예시 [문서]</th></tr></thead><tbody><tr><td>건재</td><td>Raw Stone 2 -&gt; Building Materials 1. 기본 Stone Mine: 건재 3, 작업자 3, 전력 0. Manual Stone Processor: 철판 6, 작업자 3, 전력 0</td></tr><tr><td>철판</td><td>Raw Iron 1 -&gt; Iron Plates 1. 전력형 Iron Refinery: 철판 10으로 건설, 작업자 2, 전력 10. III/IV는 기계 운영자 0명이나 원료 운반 필요</td></tr><tr><td>강철</td><td>Iron Plates 4 -&gt; Steel Bars 1. 첫 Steel Refinery: 철판 20, 작업자 2, 전력 10; 고급 무기·부품 재료</td></tr><tr><td>직물·방어구</td><td>Cotton/Hemp -&gt; Fabrics; 동물 가죽 -&gt; Leather; 철 계열 -&gt; Armour Plating/Chainmail -&gt; 방어구</td></tr><tr><td>무기</td><td>작업대 I: 철판, II: 철판+직물, III: 강철+직물. 연구·숙련·작업대가 품질 제약</td></tr><tr><td>바이오연료</td><td>Greenfruit/Wheatstraw/Hemp -&gt; Fuel -&gt; 발전기. Hemp 연료 가공은 별도 연구, 문서상 효율 2배</td></tr></tbody></table><p>근거: S-KEN-REF-10, S-KEN-REF-12. 제조비를 최종 완제품 가격으로 치환하지 않으며 가공·운반 노동도 필요하다.</p><table tabindex="0"><thead><tr><th>발전·저장</th><th>건설 재료 [문서]</th><th>출력·기능</th></tr></thead><tbody><tr><td>Small Wind Generator</td><td>철판 7 + Electrical Components 4</td><td>최대 전력 25; 옥상 배치 가능</td></tr><tr><td>Wind Generator</td><td>철판 8 + Copper 5</td><td>최대 50</td></tr><tr><td>Wind Generator II</td><td>신규: 철판 10 + Electrical Components 8</td><td>최대 100; 기존 풍력 업그레이드는 전자부품 8</td></tr><tr><td>Small Generator</td><td>철판 4 + Copper 4</td><td>Fuel 소비, 기본 40; 반복 연구로 70까지</td></tr><tr><td>Battery Bank</td><td>철판 2 + Electrical Components 4</td><td>남는 전기를 저장하고 부족할 때 공급; 용량·출력 연구 별도</td></tr></tbody></table><p>근거: S-KEN-REF-10. <strong>[추론] 풍력 최대 출력 합계가 소비량보다 크다는 것만으로 24시간 안정 공급이 보장되지 않는다.</strong> 날씨·풍속이 변하므로 배터리·연료 발전기 또는 잉여 용량이 필요하다. 소형 풍력의 정확한 최소 풍속은 덤프 간 충돌로 미확인이다.</p><h3 id="_4-5-농업과-수경재배" tabindex="-1">4.5 농업과 수경재배 <a class="header-anchor" href="#_4-5-농업과-수경재배" aria-label="Permalink to &quot;4.5 농업과 수경재배&quot;">​</a></h3><p><strong>[문서] 토양 환경은 Arid/Green/Swamp이며 지역에 여러 환경 비율이 있을 수 있다.</strong> Prospecting은 물·비옥도·광물·풍속을 보여 준다. Science는 조사 범위·속도에 영향을 준다. Farming은 수확 속도와 성공률을 높이고, 비옥도·작물의 환경 적합도는 별도다. [S-KEN-REF-10]</p><table tabindex="0"><thead><tr><th>작물</th><th>Arid / Green / Swamp 적합도</th><th style="text-align:right;">야외 기준 물/일</th><th style="text-align:right;">성장 시간</th><th>대표 용도</th></tr></thead><tbody><tr><td>Cactus</td><td>100% / 0% / 0%</td><td style="text-align:right;">2</td><td style="text-align:right;">24시간</td><td>Chewsticks·Dustwich</td></tr><tr><td>Cotton</td><td>0% / 100% / 0%</td><td style="text-align:right;">10</td><td style="text-align:right;">30시간</td><td>직물</td></tr><tr><td>Greenfruit</td><td>0% / 100% / 0%</td><td style="text-align:right;">10</td><td style="text-align:right;">23.33시간</td><td>채소·Gohan·Foodcube</td></tr><tr><td>Hemp</td><td>40% / 100% / 100%</td><td style="text-align:right;">6</td><td style="text-align:right;">21.6시간</td><td>직물·연료·Hashish</td></tr><tr><td>Riceweed</td><td>0% / 0% / 100%</td><td style="text-align:right;">10</td><td style="text-align:right;">15시간</td><td>Rice Bowl·Gohan</td></tr><tr><td>Wheatstraw</td><td>50% / 100% / 0%</td><td style="text-align:right;">5</td><td style="text-align:right;">22시간</td><td>가루·빵·연료</td></tr></tbody></table><p>표는 위키의 기준값이며 지역·설정과 노동·수확 실패를 포함한 실제 일일 식량 생산 보장은 아니다. [문서: S-KEN-REF-10]</p><p><strong>[문서] 일반 Small 농장은 해당 작물 10개로 시작하고 수확물을 써 더 큰 농장으로 업그레이드할 수 있다.</strong> 모든 작물의 최대 크기가 같지는 않다. 수경재배는 Greenfruit/Hemp/Riceweed/Wheatstraw 네 종류만 가능하며 한 설비는 작물 10+철판 4+전자부품 2, 전력 10과 물을 요구한다. 토양·비옥도 제약을 없애지만 물·전력·노동 제약은 남는다. River/Swamp Raptor는 작물을 먹으러 와 농부와 싸울 수 있고, UC에서 Hemp 농장은 불법이다. [S-KEN-REF-10]</p><h3 id="_4-6-제작-품질과-판로" tabindex="-1">4.6 제작 품질과 판로 <a class="header-anchor" href="#_4-6-제작-품질과-판로" aria-label="Permalink to &quot;4.6 제작 품질과 판로&quot;">​</a></h3><p><strong>[문서] 무기 숙련에 따른 대표 제작 등급은 Catun 1/2/3이 30/35/40, Mk I/II/III가 50/55/60, Edge Type 1이 70이다.</strong> 숙련만 높여서는 연구·작업대 상한을 넘지 못한다. Edge Type 2는 상위 품질 제작 성공으로 가능하지만 안정 생산은 아니며, Edge Type 3와 Meitou는 기본 제작으로 만들 수 없다. 반면 방어구의 높은 품질은 별도의 등급 연구보다 Armour Smith 숙련·빛·부상 상태에 좌우된다. [S-KEN-REF-12]</p><p><strong>[추론] 생산 전문가는 전투에서 빠져 있어도 장비·매각 자산을 늘리는 성장 축이다.</strong> 그러나 밤에 조명을 끄거나 부상한 장인을 계속 쓰면 실제 품질이 떨어질 수 있다. 원료 가치와 완제품 가치 차이만 보고 수익성을 계산하지 말고 제작 시간·물류 공간·판매 여행도 포함해야 한다. [문서 근거: S-KEN-REF-12]</p><h2 id="_5-캐릭터-파티" tabindex="-1">5. 캐릭터/파티 <a class="header-anchor" href="#_5-캐릭터-파티" aria-label="Permalink to &quot;5. 캐릭터/파티&quot;">​</a></h2><h3 id="_5-1-능력-체계-33개-능력의-역할과-훈련" tabindex="-1">5.1 능력 체계: 33개 능력의 역할과 훈련 <a class="header-anchor" href="#_5-1-능력-체계-33개-능력의-역할과-훈련" aria-label="Permalink to &quot;5.1 능력 체계: 33개 능력의 역할과 훈련&quot;">​</a></h3><p><strong>[문서] 기본 능력 4+근접 무기 6+원거리 3+전투 4+도둑 4+운동 2+과학·의료 4+생산 6으로, 아래 목록은 총 33개다.</strong> &#39;약 25개&#39;에 맞추어 서로 다른 능력을 합치거나 Precision Shooting을 누락하지 않는다. 위키는 분류 제목을 7계열이라고 소개하면서 원거리 능력을 별도로 설명하므로 분류 수와 개별 능력 수를 구별해야 한다. [S-KEN-REF-09]</p><table tabindex="0"><thead><tr><th>계열</th><th>능력</th><th>기능·훈련 행동 [문서]</th></tr></thead><tbody><tr><td>기본</td><td>Strength</td><td>적재·둔기 피해·중량 무기 운용·격투 피해. 무거운 짐/인물 운반, 전투</td></tr><tr><td>기본</td><td>Dexterity</td><td>베기 피해·공격/막기·재장전 속도. 베기 비중 높은 무기·격투</td></tr><tr><td>기본</td><td>Toughness</td><td>피해 저항·KO Point·상처 악화·격투 피해. 피격·패배·죽은 척하다 일어남</td></tr><tr><td>기본</td><td>Perception</td><td>원거리·이동 표적 명중. 원거리 사격</td></tr><tr><td>무기</td><td>Katanas</td><td>카타나 계열 피해, 해당 무기로 전투</td></tr><tr><td>무기</td><td>Sabres</td><td>세이버 계열 피해, 해당 무기로 전투</td></tr><tr><td>무기</td><td>Hackers</td><td>해커 계열 피해, 해당 무기로 전투</td></tr><tr><td>무기</td><td>Heavy Weapons</td><td>대형 무기 피해, 해당 무기로 전투</td></tr><tr><td>무기</td><td>Blunt Weapons</td><td>둔기 계열 피해, 해당 무기로 전투</td></tr><tr><td>무기</td><td>Polearms</td><td>장병기 피해, 해당 무기로 전투</td></tr><tr><td>원거리</td><td>Crossbows</td><td>석궁 조준·정확도·재장전, 석궁 사용</td></tr><tr><td>원거리</td><td>Turrets</td><td>고정 포탑 조준·정확도·재장전, 포탑 사용</td></tr><tr><td>원거리</td><td>Precision Shooting</td><td>아군 오사 회피, 원거리 사용·오사 경험</td></tr><tr><td>전투</td><td>Melee Attack</td><td>무장 공격 기회·방어 돌파·공격 속도, 무장 전투·훈련 허수아비</td></tr><tr><td>전투</td><td>Melee Defense</td><td>무장 막기 확률·속도, 막기·막기 실패</td></tr><tr><td>전투</td><td>Dodge</td><td>비무장 또는 휘청일 때 회피, 회피·피격</td></tr><tr><td>전투</td><td>Martial Arts</td><td>비무장 명중·기술 동작·피해·공격 속도, 비무장 전투</td></tr><tr><td>도둑</td><td>Stealth</td><td>은폐·변장·현상금 식별 회피, 근처 인물이 있을 때 은신 이동</td></tr><tr><td>도둑</td><td>Thievery</td><td>훔치기·장물 되팔기, 위험한 절도 시도</td></tr><tr><td>도둑</td><td>Lockpicking</td><td>문·상자·철창·족쇄 잠금 해제, 해정·훈련 상자</td></tr><tr><td>도둑</td><td>Assassination</td><td>은밀한 기절 성공·지속시간, 기절 시도. 즉사 암살이 아님</td></tr><tr><td>운동</td><td>Athletics</td><td>육상 달리기 속도, 가벼운 상태의 이동</td></tr><tr><td>운동</td><td>Swimming</td><td>수영 속도, 물에서 이동</td></tr><tr><td>과학·의료</td><td>Field Medic</td><td>붕대·부목 속도와 소모품 효율, 응급처치</td></tr><tr><td>과학·의료</td><td>Engineer</td><td>건설·시설 수리 속도, 건설·수리</td></tr><tr><td>과학·의료</td><td>Robotics</td><td>기계 치료와 로봇 부품 제작, 수리·관련 제작</td></tr><tr><td>과학·의료</td><td>Science</td><td>연구 속도·Prospecting, 연구·관련 작업</td></tr><tr><td>생산</td><td>Weapon Smith</td><td>무기 제작 속도·품질, 무기 제작</td></tr><tr><td>생산</td><td>Armour Smith</td><td>방어구 제작 속도·품질, 재료 가공·방어구 제작</td></tr><tr><td>생산</td><td>Crossbow Smith</td><td>석궁 품질·제작 및 볼트 제작 속도, 관련 제작</td></tr><tr><td>생산</td><td>Labouring</td><td>채광·단순 설비·직물 가공 속도, 노동</td></tr><tr><td>생산</td><td>Farming</td><td>수확 속도·성공률, 농사·곡물 가공</td></tr><tr><td>생산</td><td>Cooking</td><td>요리·양조 속도, 조리·양조</td></tr></tbody></table><p><strong>[문서] 성장 방식은 직업 레벨 배분이 아니라 사용 기반이며 종족별 경험치 배율이 있다.</strong> 예를 들어 Greenlander의 Science/Farming/Cooking은 1.2배, Scorchlander의 Weapon/Armour Smith는 1.2배, Shek의 Toughness/Melee Attack은 1.2배지만 Dexterity/Athletics는 0.8배다. 이는 최종 능력의 고정 배율이나 해당 작업의 독점 자격이 아니다. [S-KEN-REF-09]</p><h3 id="_5-2-성장-공식과-훈련의-한계" tabindex="-1">5.2 성장 공식과 훈련의 한계 <a class="header-anchor" href="#_5-2-성장-공식과-훈련의-한계" aria-label="Permalink to &quot;5.2 성장 공식과 훈련의 한계&quot;">​</a></h3><p><strong>[문서] 일부 전투 기술에는 Stronger Opponent Logic이 적용된다.</strong> 자신의 비교 능력이 상대보다 낮으면 XP가 증가하고 높으면 감소한다. 차이 <code>d = 상대 비교 능력 - 내 비교 능력</code>으로 정리하면 다음과 같다. 이 정리는 위키 계수를 식으로 옮긴 것이며 기술별 비교 대상은 동일하지 않다. [S-KEN-REF-11]</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[문서의 구간식을 정리: S-KEN-REF-11]</span></span>
<span class="line"><span>d &gt;= 0: XP 배율 = min(6, 1 + 0.10*d)</span></span>
<span class="line"><span>d &lt;  0: XP 배율 = max(0.1, 1 + 0.04*d)</span></span>
<span class="line"><span>추가 레벨 계수 = (1 - 실제 기술레벨/101)^2</span></span></code></pre></div><p><strong>[문서] 무장 공격은 내 Melee Attack과 상대 Melee Defense를 비교하되 상대가 비무장이면 Martial Arts를 쓴다.</strong> 내 무장 방어는 상대 Melee Attack/격투에 대응한다. Dexterity의 비교에 Dexterity 자체가 쓰이지 않고 공격/격투 비교를 따르며, 무기 사용 시 <code>베기/(베기+둔기)</code> 비중도 XP에 곱한다. 훈련 허수아비 Mk1/2/3은 Melee Attack을 5/10/15까지 올린다. [S-KEN-REF-11]</p><p><strong>[문서] Strength의 적재 기준은 <code>15 + Strength</code>이며, 인물 하나를 업으면 30kg가 추가된다.</strong> 이동 훈련의 Strength XP는 적재 70%에서 25% 배율에 도달하고 다른 인물을 업으면 50%까지 올라간다. 더 무겁게 한다고 이동 Strength 훈련 효율이 계속 증가하지 않는다. Athletics는 반대로 적재 때문에 훈련 효율이 줄어든다. [S-KEN-REF-11, S-KEN-REF-12]</p><p><strong>[문서] Lockpicking 성공률은 <code>min(90, 90 / 2^((잠금 난도-해정 능력)/10))</code>%이고 보통 5% 미만이면 시도할 수 없다.</strong> 난도 100은 약 58.301의 능력이 최소 기준이다. 수감 -10 보정에는 일반 시도 자격과 다른 예외가 있어 철창의 표시 확률만으로 일반 문 규칙을 역추정하면 안 된다. [S-KEN-REF-12]</p><h3 id="_5-3-파티·동물·종족의-역할" tabindex="-1">5.3 파티·동물·종족의 역할 <a class="header-anchor" href="#_5-3-파티·동물·종족의-역할" aria-label="Permalink to &quot;5.3 파티·동물·종족의 역할&quot;">​</a></h3><p><strong>[문서] 기본 직접 조종 인원 상한은 동물 포함 30이다.</strong> 정식 동료는 플레이어 인물로 편입되고 NPC 경호는 계약한 우군으로 남는다. 해방 노예도 임시 우군과 정식 동료를 구별한다. 높은 능력의 모든 포로를 철창에 넣었다고 자동 모집할 수는 없다. [S-KEN-REF-01, S-KEN-REF-04]</p><p><strong>[추론] 실용적인 분업은 전열, 사수, 정찰·해정, 의무·구조, 운반, 연구·생산이다.</strong> 고정 클래스는 아니므로 한 명이 여러 역할을 배울 수 있지만 전열과 최후 구조자를 같은 인물에게 맡기면 전투 불능 시 복구 경로가 함께 사라진다. 짐승은 큰 적재량·성장 잠재력을 제공하지만 음식과 안전한 성장 시간이 필요하다. [문서 근거: S-KEN-REF-01, S-KEN-REF-07, S-KEN-REF-09]</p><p><strong>[문서] 종족 차이는 경험치뿐 아니라 음식·회복·장비·외교·이동에도 연결된다.</strong> Skeleton은 먹지 않지만 기계 수리와 마모 회복이 필요하고, Hiver는 적은 식량·산성비 내성을 가지며, Holy Nation은 비인간과 로봇에 차별적인 반응을 한다. Swimming 설명에 익사 방지가 있어도 실제 물에서는 익사하지 않으며, Skeleton은 헤엄치지 않고 수중 이동 속도 30 game units/s가 고정된다. 산성 물의 피해는 별도다. [S-KEN-REF-03, S-KEN-REF-07, S-KEN-REF-12, S-KEN-REF-15]</p><h3 id="_5-4-신체·치료·절단·의수의족" tabindex="-1">5.4 신체·치료·절단·의수의족 <a class="header-anchor" href="#_5-4-신체·치료·절단·의수의족" aria-label="Permalink to &quot;5.4 신체·치료·절단·의수의족&quot;">​</a></h3><p><strong>[문서] 건강은 머리·가슴·배·좌우 팔·좌우 다리의 7부위와 혈액/기름으로 나뉜다.</strong> 중요 부위가 0 아래로 내려가면 기절할 수 있고, KO Point보다 낮으면 회복 혼수에 빠져 중요 부위가 회복될 때까지 일어나지 못한다. 다리 손상은 달리기·도주, 팔 손상은 무기 운용·작업을 망가뜨린다. 타박상은 스스로 회복하지만 큰 베기 상처는 출혈·악화를 막도록 붕대나 수리가 필요하다. [S-KEN-REF-07, S-KEN-REF-16]</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[문서: S-KEN-REF-11]</span></span>
<span class="line"><span>T = Toughness</span></span>
<span class="line"><span>피해 저항률 = clamp(-0.65 + 0.013*T, -0.65, 0.65)</span></span>
<span class="line"><span>KO Point = -10 - 0.75*T</span></span>
<span class="line"><span>상처 악화 계수 = 1.7 - 0.0167*T</span></span></code></pre></div><p><strong>[추론] T=0이면 같은 방어구에서 피해가 1.65배, T=50이면 1배, T=100이면 0.35배다.</strong> KO Point는 각각 -10/-47.5/-85다. Toughness는 부위 최대 HP를 무조건 늘리는 수치가 아니라 생존 판정과 실제 피해를 바꾼다. 원문상의 상처 악화 계수는 부상 크기 등의 추가 조건까지 포함한 최종 초당 손실 공식이 아니다. [S-KEN-REF-11, S-KEN-REF-16]</p><p><strong>[문서] 정상 침대의 유기체 회복은 8배, 야전 침상은 4배이며 자는 동안 상처 악화가 멈추지만 미처치 베기 상처가 저절로 완치되지는 않는다.</strong> 혈액은 출혈이 멎어야 재생되고 침대에서 2배 속도로 회복한다. Field Medic와 Robotics의 작업 속도 지표는 각각 <code>3 + 0.42 × 해당 능력</code>이며 키트 수준·남은 충전량도 중요하다. [S-KEN-REF-07, S-KEN-REF-09]</p><p><strong>[문서] 부목은 실제 조직을 완치하지 않고 팔·다리의 유효 HP를 임시 보조한다.</strong> Small Splint는 최대 약 26, 일반 부목은 약 51까지 보조하지만 유효 HP 50을 넘기지 못하는 제약이 있다. 심한 음수 HP에서는 표시상 효과가 드러나지 않을 수 있다. 다리가 조금 회복된 인물의 구조 이동에 특히 유용하다. [S-KEN-REF-07]</p><table tabindex="0"><thead><tr><th>상태</th><th>발생·해결 [문서]</th></tr></thead><tbody><tr><td>절단 Rare, 기본</td><td>팔다리 HP가 최대 HP의 -100%를 넘게 손상되고 타격을 받아야 분리. 모든 종족에 &#39;-100 HP&#39; 고정이 아님</td></tr><tr><td>절단 Frequent</td><td>그 음수 최대치 아래로 내려가면 상처 악화만으로도 분리</td></tr><tr><td>절단 Never</td><td>해당 게임 설정으로 일반 절단 방지</td></tr><tr><td>의수의족 장착</td><td>자연 팔다리를 잃은 뒤 Limbs 슬롯에 좌/우가 맞는 부품 장착. Skeleton도 원래 팔다리를 먼저 잃어야 함</td></tr><tr><td>수리</td><td>기계 베기 피해에는 수리키트. 받았던 피해의 4%가 마모로 최대 HP를 낮추며 수리침대로 복구</td></tr><tr><td>동물</td><td>절단·의수의족 사용 불가</td></tr></tbody></table><p>근거: S-KEN-REF-16, S-KEN-REF-17. 절단 시 출혈 처치가 우선이며 고급 의지를 사는 것만으로 다른 부위의 손상까지 없애지는 못한다.</p><table tabindex="0"><thead><tr><th>Masterwork 의지 예</th><th>HP·대표 보정 [문서]</th><th>거래·역할의 대가</th></tr></thead><tbody><tr><td>Skeleton Arm</td><td>170HP, Dexterity +25%</td><td>양팔 보정은 곱연산: 1.25²=1.5625배; 해정·절도·수영 페널티</td></tr><tr><td>KLR Series Arm</td><td>245HP, Strength/Dexterity 각각 +10%</td><td>방어적 선택, 손재주·수영 페널티</td></tr><tr><td>Industrial Lifter Arm</td><td>195HP, Strength +23.75%</td><td>중량 무기·운반, 해정·절도 페널티</td></tr><tr><td>Steady Arm, 왼팔</td><td>145HP, Crossbows +25%, Dexterity +20%</td><td>사격 특화; 기본 제작 불가</td></tr><tr><td>Thief&#39;s Arm, 오른팔</td><td>145HP, Lockpicking/Thievery +25%, Dexterity +20%</td><td>도둑 특화; 기본 제작 불가</td></tr><tr><td>Scout Leg</td><td>145HP, Athletics +38%</td><td>빠른 이동, 다른 기능·정치 접근과 교환</td></tr><tr><td>KLR Series Leg</td><td>290HP</td><td>내구도 중심, 은신·수영에 큰 페널티</td></tr></tbody></table><p>표 근거: S-KEN-REF-17. <strong>[문서] HN 관계 +50 미만에서 로봇 의지는 로봇으로 취급되어 공격 원인이 된다.</strong> 동맹이면 일반 공격 예외가 있어도 Phoenix·사제·상점 등의 대화 접근이 계속 제한될 수 있으므로 &#39;동맹이면 모든 문제가 해결&#39;은 아니다. [S-KEN-REF-17]</p><h2 id="_6-전투" tabindex="-1">6. 전투 <a class="header-anchor" href="#_6-전투" aria-label="Permalink to &quot;6. 전투&quot;">​</a></h2><h3 id="_6-1-조작과-전술의-단위" tabindex="-1">6.1 조작과 전술의 단위 <a class="header-anchor" href="#_6-1-조작과-전술의-단위" aria-label="Permalink to &quot;6.1 조작과 전술의 단위&quot;">​</a></h3><p><strong>[문서] 전투는 인물의 기술·장비와 실제 동작·거리·상태에 의존한다.</strong> 무장하면 Melee Defense로 막고, 비무장이면 Dodge로 피한다. 무장 상태에서도 휘청이는 중에는 회피할 수 있다. 석궁은 호환 볼트와 RANGED 활성화가 필요하고 근접전에는 보조 무기가 중요하다. 동료 오사가 실제로 중상·사망을 일으킬 수 있다. [S-KEN-REF-11, S-KEN-REF-18]</p><p><strong>[추론] 전투력은 하나의 DPS로 환원되지 않는다.</strong> 적에게 접근 가능한 수, 무기의 범위, 실내 보정, 다리 부상으로 이탈할 수 있는지, 사선에 아군이 있는지가 결과를 바꾼다. 아래 확률은 두 인물이 유효하게 공격·방어를 시도하는 조건의 모델이지, 멀리 떨어져 있어도 매초 추첨되는 전역 명중 공식이 아니다. [문서 근거: S-KEN-REF-09, S-KEN-REF-11, S-KEN-REF-18]</p><h3 id="_6-2-공격-기회·막기·회피" tabindex="-1">6.2 공격 기회·막기·회피 <a class="header-anchor" href="#_6-2-공격-기회·막기·회피" aria-label="Permalink to &quot;6.2 공격 기회·막기·회피&quot;">​</a></h3><p><strong>[문서] Melee Attack 설명은 공격권의 가중치와 방어 성공률을 분리한다.</strong> 높은 공격 능력 쪽의 차이가 ΔA≥0이면 가중치를 <code>(1+0.025×ΔA):1</code>로 설명한다. 차이 40에서는 2:1이므로 약 66.7%의 공격 기회다. 이 문서화는 1.0.65 표기가 있으며 FCS 툴팁의 계수가 실제와 다르다는 경고를 포함한다. [S-KEN-REF-11]</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[문서의 구간식을 정리: S-KEN-REF-11]</span></span>
<span class="line"><span>A = 공격자의 보정 후 공격 능력</span></span>
<span class="line"><span>D = 방어자의 보정 후 Melee Defense, 비무장은 대응 Dodge</span></span>
<span class="line"><span>x = D - A</span></span>
<span class="line"><span>x &gt;= 0: 방어 성공률 = min(95, 70 + 1.2*x)%</span></span>
<span class="line"><span>x &lt;  0: 방어 성공률 = (70 + 1.5*x)%  [극단 구간 하한은 이번 자료로 미확인]</span></span></code></pre></div><p><strong>[문서] Dodge도 같은 방식으로 설명되며, 방어 능력이 상대 공격보다 약 21 높으면 성공률 상한 95%에 도달한다.</strong> A=D이면 70%, D=A+10이면 82%, D=A-10이면 55%다. 모든 무장 캐릭터가 막기와 회피를 두 번 연속 판정해 피해를 없애는 구조는 아니다. [S-KEN-REF-11]</p><p><strong>[미확인] 위 식의 공격/방어 동작 선택·최저 확률·다중 교전 예외를 이번에 엔진 수준에서 검증하지 않았다.</strong> 따라서 음수로 계산되는 구간을 실제 음수 확률이라고 해석하거나, 모든 공격의 최종 명중률을 무조건 <code>1-막기 확률</code>로 고정하지 않는다.</p><h3 id="_6-3-속도·무기-필요-strength" tabindex="-1">6.3 속도·무기 필요 Strength <a class="header-anchor" href="#_6-3-속도·무기-필요-strength" aria-label="Permalink to &quot;6.3 속도·무기 필요 Strength&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[문서의 커뮤니티 모델: S-KEN-REF-11]</span></span>
<span class="line"><span>무기 필요 Strength = max(40 × 무기 둔기 피해 계수, 보정 전 무기 무게)</span></span>
<span class="line"><span>격투 필요 Strength = 0.8 × Martial Arts</span></span>
<span class="line"><span>기본 공격 속도 지표 ≈ 0.765 + 0.00152 × Melee Attack + 0.00228 × Dexterity</span></span>
<span class="line"><span>최종 공격 속도 = 기본 지표 × Combat Speed 보정, 상한 1.2</span></span>
<span class="line"><span>막기 속도 상한 = 4.0</span></span></code></pre></div><p><strong>[문서] 필요 Strength보다 20 이상 부족하면 Combat Speed가 최대 약 47.5% 감소한다.</strong> 충분한 Strength를 이미 가진 뒤에는 추가 Strength가 이 부족 페널티를 넘어 무조건 공격 속도를 높이지 않는다. 갑옷·배낭·적재도 Combat Speed에 관여한다. Dodge 애니메이션 속도는 Dodge 레벨이나 Combat Speed로 빨라지지 않는다. [S-KEN-REF-11]</p><p><strong>[추론] Attack=Dexterity=100이면 기본 지표 1.145, Wooden Sandals의 1.05배를 적용하면 1.20225지만 상한으로 1.2가 된다.</strong> 반면 근력이 부족해 둔한 고급 무기는 값싼 경량 무기보다 실전에서 나쁠 수 있다. &#39;모든 무기는 무게의 두 배 Strength가 필요&#39;라는 간편식은 카타나·장병기·일부 세이버 등에 틀리므로 쓰지 않는다. [S-KEN-REF-11]</p><h3 id="_6-4-피해·갑옷-층·관통" tabindex="-1">6.4 피해·갑옷 층·관통 <a class="header-anchor" href="#_6-4-피해·갑옷-층·관통" aria-label="Permalink to &quot;6.4 피해·갑옷 층·관통&quot;">​</a></h3><p><strong>[문서] 무기는 Cut/Blunt 피해, 출혈 배율, 길이, 공격/방어·실내·대상 종류 보정을 가진다.</strong> Strength는 무기의 성장 둔기 피해에서 75%, 해당 무기 숙련은 25%의 기여로 설명되며, Dexterity는 베기와 속도에 중요하다. 원거리 Pierce는 일반 베기와 다른 Harpoon Resistance 처리가 있다. 아래는 이미 산출된 원피해가 몸에 도달하는 과정이다. 완전한 원피해 생성식은 이번 자료에서 확정하지 않는다. [S-KEN-REF-09, S-KEN-REF-11, S-KEN-REF-16]</p><p><strong>[문서] Coverage 80%는 매번 피해를 80% 덮는 것이 아니라, 해당 부위에 맞은 공격 중 80%에서 그 방어구가 적용된다는 뜻이다.</strong> 겹치는 방어구는 Head -&gt; Armour -&gt; Pants -&gt; Shirt -&gt; Boots 순서로 처리된다. 환경 보호는 이 층별 확률 계산과 달리 합산이다. [S-KEN-REF-11]</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[문서의 단일 방어층 모델: S-KEN-REF-11, S-KEN-REF-16]</span></span>
<span class="line"><span>B = 원 둔기 피해, C = 원 베기 피해</span></span>
<span class="line"><span>RB = 둔기 저항, RC = 베기 저항, E = 베기 저항 효율, RT = Toughness 저항</span></span>
<span class="line"><span>남은 둔기 = B × (1-RB)</span></span>
<span class="line"><span>다음 층으로 가는 베기 = C × (1-RC)</span></span>
<span class="line"><span>추가 타박상 = C × RC × (1-E)</span></span>
<span class="line"><span>몸에 적용되는 피해에 Toughness의 (1-RT) 보정</span></span></code></pre></div><p><strong>[문서] 베기 저항으로 막은 부분 중 효율이 부족한 몫은 타박상으로 전환되고 다음 방어구 층으로 다시 막을 수 없다.</strong> 단일 방어구의 베기 저항 상한은 90%다. 예를 들어 C=50, RC=75%, E=60%, Toughness 보정 없음이면 베기 12.5와 타박상 15, 합계 27.5를 받는다. &#39;Cut Resistance 75%&#39;만 보고 총 피해가 12.5라고 계산하면 틀린다. [S-KEN-REF-11]</p><p><strong>[문서] 둔기 100, 둔기 저항 14%, Toughness 70의 저항 26%라면 <code>100×0.86×0.74=63.64</code>다.</strong> Armour Penetration 30%는 저항값에서 30%p를 빼는 것이 아니라 <code>기존 저항×0.7</code>로 설명된다. 단, 베기-&gt;타박상 전환에는 관통 전 저항을 사용하는 예외가 문서화되어 있으므로 단순한 관통 수식을 전환 피해까지 무조건 적용하지 않는다. [S-KEN-REF-11]</p><p><strong>[문서] Harpoon Resistance는 비율이 아니라 막을 수 있는 Pierce 피해량 기준이다.</strong> 예를 들어 Pierce 50을 Harpoon 35, Cut 44%, 효율 60%의 Dustcoat가 받으면 35의 보호분에서 타박상 <code>35×0.44×0.4=6.16</code>, 보호를 넘은 15는 직접 베기 피해로 남고 이후 Toughness가 적용된다. <strong>[미확인] 복수 Harpoon 방어층의 정확한 전달 과정은 원 위키도 불확실하다고 표시하므로 확정하지 않는다.</strong> [S-KEN-REF-16]</p><h3 id="_6-5-무기-계열과-사격" tabindex="-1">6.5 무기 계열과 사격 <a class="header-anchor" href="#_6-5-무기-계열과-사격" aria-label="Permalink to &quot;6.5 무기 계열과 사격&quot;">​</a></h3><table tabindex="0"><thead><tr><th>계열</th><th>강점·대가 [문서]</th></tr></thead><tbody><tr><td>Katanas</td><td>베기·공격적 보정·빠른 동작 중심, 중장갑 상대에는 관통 특성을 확인</td></tr><tr><td>Sabres</td><td>베기 비중 높고 방어 보정 중심, 공격 보정과 교환</td></tr><tr><td>Hackers</td><td>베기+둔기 혼합, 관통·로봇 상대 보너스, 동물 상대 불리한 보정</td></tr><tr><td>Heavy Weapons</td><td>높은 혼합 피해·긴 범위, 큰 Strength 요구·실내 페널티</td></tr><tr><td>Blunt</td><td>타박상·기절 중심, 베기 부족으로 Dexterity 훈련에 불리; 둔기라도 모든 상황 비살상 보장은 아님</td></tr><tr><td>Polearms</td><td>긴 범위·공격 보정·동물 대응, 실내 페널티; Staff 등 예외</td></tr><tr><td>Martial Arts</td><td>숙련에 따라 동작 해금, Strength/Toughness가 피해에 기여, 무장 막기 대신 회피·적재 관리</td></tr></tbody></table><p>근거: S-KEN-REF-09, S-KEN-REF-11, S-KEN-REF-16. 계열의 경향이며 모든 무기의 한손/양손 사용 조건이 동일하다는 뜻은 아니다.</p><p><strong>[문서] 석궁 탄약은 Toothpicks 40발/243c, Regulars 30발/243c, Heavies 20발/272c, Longs 10발/389c의 기본 묶음이다.</strong> Junkbow/Tooth Pick은 Toothpicks, Ranger/Oldworld Bow는 Regulars, Spring Bat은 Heavies, Eagle&#39;s Cross는 Longs를 쓴다. Precision Shooting은 레벨당 오사 회피 1.5%로 설명되지만 부상·암흑·먼지폭풍·장비 보정이 있으므로 일정 기본 레벨만으로 모든 오사를 없앴다고 보장하지 않는다. [S-KEN-REF-18]</p><h2 id="_7-지도-세계" tabindex="-1">7. 지도/세계 <a class="header-anchor" href="#_7-지도-세계" aria-label="Permalink to &quot;7. 지도/세계&quot;">​</a></h2><h3 id="_7-1-지역은-난이도뿐-아니라-생계·정치·환경의-묶음" tabindex="-1">7.1 지역은 난이도뿐 아니라 생계·정치·환경의 묶음 <a class="header-anchor" href="#_7-1-지역은-난이도뿐-아니라-생계·정치·환경의-묶음" aria-label="Permalink to &quot;7.1 지역은 난이도뿐 아니라 생계·정치·환경의 묶음&quot;">​</a></h3><table tabindex="0"><thead><tr><th>지역군</th><th>세계에서의 역할 [문서]</th><th>경로 판단 [추론]</th></tr></thead><tbody><tr><td>Border Zone / The Hub / Squin 인근</td><td>HN·Shek 사이, 도적·Trade Ninjas·Waystation</td><td>경비·시장과 가까운 생존 루프를 빌릴 수 있음</td></tr><tr><td>Okran 지역</td><td>HN 핵심권, 비옥한 농업 입지</td><td>토양의 이점과 종족·종교·의지 제약을 함께 계산</td></tr><tr><td>Great Desert / Heng / UC 도시권</td><td>상인·노예경제·귀족·순찰</td><td>합법 판로와 가난·도망 노예 식별 위험 공존</td></tr><tr><td>Vain / Western Hive</td><td>Hive 마을망, 산성 물·비</td><td>종족·보호구·거래 접근에 따라 여행 비용 변화</td></tr><tr><td>Swamp / Shark</td><td>갱단 도시·쌀·Hemp 농업</td><td>생산 적합도와 지역 폭력·범죄 판로 결합</td></tr><tr><td>Fog Islands / Mongrel</td><td>안개 속 고립 도시, Fogmen 위협</td><td>도시 내부 서비스와 도시 밖 납치 위험의 차이가 큼</td></tr><tr><td>Cannibal Plains / 북부</td><td>식인종과 Cannibal Hunters·Deadcat</td><td>쓰러졌을 때 포식 전에 구조할 시간 필요</td></tr><tr><td>Deadlands / Black Desert</td><td>산성비·산성 지면·가스 구역</td><td>전투력보다 환경 보호와 종족이 먼저 병목</td></tr><tr><td>Venge</td><td>주간 이동 광선의 화상</td><td>시간대와 내성으로 위험을 우회</td></tr><tr><td>남동부</td><td>Crab Raiders/Reavers/Skeleton Bandits/Skin Bandits 경쟁</td><td>지도자 제거가 주변 거점과 세력 구성을 바꿈</td></tr></tbody></table><p>근거: S-KEN-REF-01, S-KEN-REF-03, S-KEN-REF-10, S-KEN-REF-14, S-KEN-REF-15. 모든 지역·유적의 좌표 사전은 아니며 세계 규모를 절차 생성 또는 플레이어 중심 스케일링으로 오해하지 않도록 기능을 정리했다.</p><h3 id="_7-2-환경-위험" tabindex="-1">7.2 환경 위험 <a class="header-anchor" href="#_7-2-환경-위험" aria-label="Permalink to &quot;7.2 환경 위험&quot;">​</a></h3><p><strong>[문서] 산성비는 유기체 부위에 타박상 피해를 주며 실내·쉼터·보호구로 막는다.</strong> Hiver/Skeleton/동물은 산성비 면역이다. 산성 물에 들어갔을 때는 산성비 보호구가 적용되지 않고, 산성 지면에는 신발 문제가 추가된다. Venge 광선은 유기체에 베기성 화상을 주므로 노출 후 붕대가 필요하다. 가스는 주로 가슴에 피해를 준다. [S-KEN-REF-15]</p><p><strong>[문서] 먼지폭풍은 시야를 줄여 은신을 돕지만 Melee Attack/Martial Arts를 최대 10 낮춘다.</strong> Perception 감소량은 전용 능력 문서의 최대 20%와 Weather Effects의 33.5%가 충돌한다. <strong>[미확인] 정확한 지각 감소 상한은 여기서 확정하지 않는다.</strong> 바람은 동시에 발전량을 바꾸므로 날씨는 전투와 산업 모두의 입력이다. [S-KEN-REF-11, S-KEN-REF-15, S-KEN-REF-10]</p><h3 id="_7-3-world-states와-town-overrides" tabindex="-1">7.3 World States와 Town Overrides <a class="header-anchor" href="#_7-3-world-states와-town-overrides" aria-label="Permalink to &quot;7.3 World States와 Town Overrides&quot;">​</a></h3><p><strong>[문서] World States는 중요 인물의 생존·자유·수감 상태를 조건으로 도시 교체와 야외 Homeless Spawns를 바꾼다.</strong> 일반 조건에서 &#39;살아 있음/Okay&#39;는 살아 있고 자유로움을 뜻하고, &#39;죽음&#39; 조건은 수감으로도 충족되는 경우가 많다. 그러나 Dust King의 Bandit Demands 중단은 사망을 요구하며 Hive 여왕 구출 공격은 살해가 아니라 납치 상태를 요구하는 예외가 있다. [S-KEN-REF-14]</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[추론: S-KEN-REF-14]</span></span>
<span class="line"><span>중요 인물 상태 변경</span></span>
<span class="line"><span> -&gt; 해당 World State 조건 재평가</span></span>
<span class="line"><span> -&gt; 조건에 맞는 Town Override 선택 + 지역 스폰 변화</span></span>
<span class="line"><span> -&gt; 통치 세력/거점 상태/순찰/보복·구출 사건 변화</span></span>
<span class="line"><span></span></span>
<span class="line"><span>수감 인물 석방 -&gt; 일부 스폰·도시 상태가 다시 달라질 수 있음</span></span></code></pre></div><p><strong>[문서] 여러 Town Override가 동시에 유효하면 더 많은 World State 조건을 가진 항목이 우선하고, 같으면 override 목록의 더 위 항목을 선택한다.</strong> 주민을 많이 죽여 장소가 DEAD가 되는 상태와 지정 Override로 폐허가 되는 상태는 다르다. &#39;도시를 습격했으니 자동으로 플레이어 영토가 됨&#39;은 이 규칙이 아니다. [S-KEN-REF-14]</p><table tabindex="0"><thead><tr><th>중요 조건 집단</th><th>확인된 변화 범위 [문서]</th></tr></thead><tbody><tr><td>HN: Phoenix·Seta·Valtena</td><td>Stack/Bad Teeth/Blister Hill/Rebirth/요새 등의 교체, 군대 해체 뒤 Strayed Paladin 출현. 세 지도자를 처리해도 Holy Farms·Narko&#39;s Trap 등 일부 거점은 존속</td></tr><tr><td>UC: Tengu·지역 귀족</td><td>Heft/Heng/Sho-Battai/Stoat 등의 조건 분기, 해체 뒤 Samurai Rogue 출현. Tengu&#39;s Vault와 Farming Village는 계속 UC에 남음</td></tr><tr><td>북동부 노예 거점</td><td>Eyesocket/Slave Farm/South Stone Camp/Stone Camp는 각 거점 귀족 상태 중심. 전체 제국 황제 상태와 동일한 조건이 아님</td></tr><tr><td>남서부 UC</td><td>Clownsteady/Drifter&#39;s Last/노예시장 등은 복수 귀족이 연결; Tengu 상태가 영향 주지 않는 별도 권역</td></tr><tr><td>Shek</td><td>Esata 제거 후 Mukai 승계, Admag/Squin 교체 분기</td></tr><tr><td>남동부</td><td>지도자 제거 후 Ark/Crab Town/Iron HQ/Skinhouse 등이 다른 세력 또는 폐허 상태로 전환 가능</td></tr><tr><td>Hive 여왕</td><td>여왕 사망·납치로 해당 Hive 마을이 Deadhive Overrun으로 교체될 수 있음</td></tr><tr><td>Swamp 갱단</td><td>Shark/Grayflayer Village/Stone Rat Village 등의 통치·상태가 갱단 지도자 조건에 연결</td></tr></tbody></table><p>근거: S-KEN-REF-14. 개별 도시의 모든 AND/OR 조건과 우선순위 목록은 읽은 개요만으로 복원하지 않았으며, 표를 &#39;지도자 하나만 잡으면 항상 같은 결과&#39;의 보장표로 쓰지 않는다.</p><p><strong>[문서] 일부 세력은 지도자 제거로 사실상 전멸하지만 다수는 잔당·잔존 거점·보복이 남는다.</strong> 일부 보복은 지도자 제거 뒤에도 끝없이 이어질 수 있다. 수감자를 풀어 주면 연계 스폰이 복원되고 Stack/Bad Teeth 등은 도시 상태가 다시 바뀔 수도 있다. [S-KEN-REF-14]</p><p><strong>[미확인] 구매 건물 보존은 출처가 충돌한다.</strong> 기존 구조 보고서는 일부 도시 교체에서 내부 자산 손실 가능성을 경고하지만, 이번에 읽은 Town Overrides는 구매 건물이 파괴·손실되지 않는다고 쓴다. 건물 소유권·실내 설비·재고를 구분한 재현이 없어 어느 쪽도 전면 보장하지 않는다. [S-KEN-REF-01, S-KEN-REF-14]</p><h2 id="_8-외교-세력" tabindex="-1">8. 외교/세력 <a class="header-anchor" href="#_8-외교-세력" aria-label="Permalink to &quot;8. 외교/세력&quot;">​</a></h2><h3 id="_8-1-관계-수치와-정치적-접근" tabindex="-1">8.1 관계 수치와 정치적 접근 <a class="header-anchor" href="#_8-1-관계-수치와-정치적-접근" aria-label="Permalink to &quot;8.1 관계 수치와 정치적 접근&quot;">​</a></h3><p><strong>[문서] 관계 +50 이상이면 Allied, -30 이하이면 Enemy다.</strong> 공격·현상범 인도·해방·특수 가입 대사가 관계를 바꾸며 일부 세력은 Pacifier로 회복할 수 있지만 모든 세력이 그런 수단을 갖지는 않는다. 동맹은 다른 세력과의 자동 전쟁 선언이 아니며, 명시적 적대 약속이나 특정 지도자 인도 대사가 별도 관계 변경을 일으킨다. [S-KEN-REF-03]</p><table tabindex="0"><thead><tr><th>세력</th><th>사회·관계 [문서]</th><th>통행·정착에 나타나는 규칙</th></tr></thead><tbody><tr><td>Holy Nation</td><td>Okran 신앙, 인간 중심·여성 종속, Shek/Hiver 차별, Skeleton/의지 적대. UC·Shek과 충돌</td><td>The Holy Flame을 가진 인간, 특히 남성의 대화가 비인간 인도 요구를 누그러뜨릴 수 있음. Prayer Day는 돈 대신 종교적 순응을 요구</td></tr><tr><td>United Cities</td><td>귀족 지배, 부를 중시, Slave Traders·Traders Guild와 결합. Rebel Farmers의 반대</td><td>빈곤·노예 신분·범죄·가방 수색이 위험. 영향권 야외 기지 Tax Man Visit 3,000c</td></tr><tr><td>Shek Kingdom</td><td>전사 문화, Esata가 소모전을 억제; Kral&#39;s Chosen·Berserkers 등의 분파</td><td>거점 조공은 현금이 아니라 식량 저장고에서 가져가는 방식. 전투 공적·현상범 대사가 큰 관계 변화</td></tr><tr><td>Slave Traders</td><td>노예 상점·농장·광산·운송</td><td>중립이어도 근처 의식불명 인물을 치료한 뒤 노예화할 수 있음</td></tr><tr><td>Manhunters / Slave Hunters</td><td>UC 권역에서 포획 후 판매</td><td>약한 인물을 도망 노예로 몰아 공격 가능. UC/TG 동맹·인원 조건 등이 표적 선택에 영향</td></tr><tr><td>Anti-Slavers</td><td>Tinfist·Grey 중심의 반노예 세력</td><td>Grey 가입 대사로 UC/TG/Slave Traders 각각 -30; 노예 신분 해소 대화도 존재</td></tr><tr><td>Flotsam Ninjas</td><td>HN에서 도망친 여성·노예 중심</td><td>Moll에게 HN 타도를 맹세하는 가입은 HN -75</td></tr><tr><td>Western Hive</td><td>Vain·Dreg의 마을망</td><td>Hive Exile의 Hiveless 거래 문제처럼 인물 상태가 상점 접근에 관여</td></tr></tbody></table><p>근거: S-KEN-REF-01, S-KEN-REF-03, S-KEN-REF-04. 종족 차별을 &#39;모든 NPC가 매 순간 같은 순서로 즉시 공격&#39;이라는 보편 행동으로 단순화하지 않는다.</p><h3 id="_8-2-현상금과-범죄" tabindex="-1">8.2 현상금과 범죄 <a class="header-anchor" href="#_8-2-현상금과-범죄" aria-label="Permalink to &quot;8.2 현상금과 범죄&quot;">​</a></h3><p><strong>[문서] 현상금은 인물과 발행 세력에 붙는다.</strong> 범죄 목격 여부와 관할이 중요하며 어느 한 세력의 현상금이 있다고 모든 도시가 동일하게 체포하지 않는다. 신분 식별에는 시간이 걸릴 수 있고 큰 현상금일수록 더 넓게 알아본다. NPC의 class와 Diplomatic Status에도 예외가 있다. [S-KEN-REF-05]</p><table tabindex="0"><thead><tr><th>범죄</th><th style="text-align:right;">추가 현상금</th><th style="text-align:right;">자연 소멸 기준 시간</th><th style="text-align:right;">복역 기준 시간</th></tr></thead><tbody><tr><td>Trespassing, 무단침입</td><td style="text-align:right;">100c</td><td style="text-align:right;">4시간</td><td style="text-align:right;">2시간</td></tr><tr><td>Looting, 약탈</td><td style="text-align:right;">500c</td><td style="text-align:right;">20시간</td><td style="text-align:right;">10시간</td></tr><tr><td>Assault, 폭행</td><td style="text-align:right;">500c</td><td style="text-align:right;">20시간</td><td style="text-align:right;">10시간</td></tr><tr><td>Burglary, 잠금 침입</td><td style="text-align:right;">1,000c</td><td style="text-align:right;">40시간</td><td style="text-align:right;">20시간</td></tr><tr><td>Theft, 절도</td><td style="text-align:right;">2,500c</td><td style="text-align:right;">100시간</td><td style="text-align:right;">50시간</td></tr><tr><td>Escaping Prison, 탈옥</td><td style="text-align:right;">2,500c</td><td style="text-align:right;">100시간</td><td style="text-align:right;">50시간</td></tr><tr><td>Refusing Bag Check, UC 수색 거부</td><td style="text-align:right;">4,000c</td><td style="text-align:right;">160시간</td><td style="text-align:right;">80시간</td></tr><tr><td>Terrorism, 외교 인물 공격·노예 해방 등</td><td style="text-align:right;">5,000c</td><td style="text-align:right;">200시간</td><td style="text-align:right;">100시간</td></tr><tr><td>Kidnapping, 납치</td><td style="text-align:right;">5,000c</td><td style="text-align:right;">200시간</td><td style="text-align:right;">100시간</td></tr><tr><td>Uniform Theft, 도난 제복 발각</td><td style="text-align:right;">5,000c</td><td style="text-align:right;">200시간</td><td style="text-align:right;">100시간</td></tr></tbody></table><p>표 근거: S-KEN-REF-05. 자연 소멸은 추가 현상금 100c당 4시간, 복역은 그 절반이라는 문서 규칙이며 Notorious 예외가 먼저 적용된다.</p><p><strong>[문서] 현상금이 10,000c를 초과하면 Notorious가 되어 자연 소멸하지 않는다.</strong> 구금 중에는 25,000c 이하가 복역으로 사라질 수 있지만 초과하면 경찰 책임자에게 보석금을 내는 방식 등이 필요하다. 보석금은 현상금의 2배다. 특정 세력이 노예화하면 그 세력에 대한 현상금이 지워질 수 있다. 간헐적 소멸·스폰 누락 버그는 정상 보장 규칙이 아니다. [S-KEN-REF-05]</p><p><strong>[문서] 현상범은 생포 인도 시 전액, 시체는 절반이다.</strong> 누가 제압했는지는 중요하지 않고 인도자가 보상을 받는다. 대화 인도는 보통 관계 +2, HN에 보수를 사양하면 +5다. 직접 철창에 넣으면 돈을 받을 수 있어도 대화의 관계 보상과 같지 않다. [S-KEN-REF-05]</p><table tabindex="0"><thead><tr><th>대상</th><th style="text-align:right;">대표 현상금 [문서]</th><th>특수 관계 변화 예</th></tr></thead><tbody><tr><td>Bugmaster</td><td style="text-align:right;">Shek/UC 100,000c</td><td>Shek 인도에서 적대 수용·기존 동맹 조건 충족 시 Shek +70/HN -80</td></tr><tr><td>Holy Lord Phoenix</td><td style="text-align:right;">100,000c</td><td>Shek +70/HN -75 등, 받는 세력에 따라 다름</td></tr><tr><td>High Inquisitor Seta/Valtena</td><td style="text-align:right;">각각 40,000c</td><td>일반 +2가 아니라 수령인·세력별 큰 변화</td></tr><tr><td>Dust King</td><td style="text-align:right;">35,000c</td><td>보통 현상금 인도 루프의 목표</td></tr><tr><td>Savant</td><td style="text-align:right;">80,000c</td><td>UC 인도, Skin Bandits 지도자 상태도 변화</td></tr><tr><td>Fog Prince Head</td><td style="text-align:right;">물품 판매 6,000c</td><td>경찰 인도가 아닌 머리 전리품 판매, 관계 보상 없음</td></tr></tbody></table><p>근거: S-KEN-REF-05. 같은 대상에게 여러 세력이 보상을 걸어도 동일 인도 한 번에 모든 보상과 모든 관계 변화가 합산되는 것은 아니다.</p><h3 id="_8-3-노예-경제와-해방" tabindex="-1">8.3 노예 경제와 해방 <a class="header-anchor" href="#_8-3-노예-경제와-해방" aria-label="Permalink to &quot;8.3 노예 경제와 해방&quot;">​</a></h3><p><strong>[문서] 플레이어는 타인을 노예상에게 팔 수 있으나 자기 소유의 강제 노동 노예를 경영하는 시스템은 없다.</strong> 일반 포획 대상 인도 보상은 400c, Rebirth 인도는 500c 또는 HN 관계 +1로 설명된다. FCS class상 Bandits/Slaves/Adventurer/Civilian 계열은 거래 가능하지만 군인·외교 인물은 보통 대화 인도 대상이 아니다. 철창에 넣어 강제 노예화되는 예외와 유상 대화 인도 자격을 구별해야 한다. [S-KEN-REF-04]</p><p><strong>[문서] 노예 구매는 Slave Traders +1, 구매 대상의 원 세력 +4의 관계 효과가 있다.</strong> 구매한 인물은 우군이 되어 따라오거나 도망가며, 조건이 맞을 때만 정식 모집된다. 플레이어가 직접 팔았다는 기억은 감사·합류에 불리하게 작동할 수 있다. 노예 구입 비용 전액이 &#39;동료 고용비&#39;와 같은 확정 결과를 사는 것은 아니다. [S-KEN-REF-04]</p><p><strong>[문서] 플레이어가 노예화되면 무기·장비를 빼앗기고 족쇄를 차며 기존 Jobs가 Obedient Slave로 대체된다.</strong> 노동·이동·밤의 철창 생활을 명령받고, 노예상은 노동력을 유지하려고 치료하며 허기를 약 100에 유지한다. 탈출하려면 족쇄/철창 해정, 은신, 변장, 경비 기절, 다른 포로의 해방과 소란 등을 활용한다. [S-KEN-REF-04]</p><p><strong>[문서] 탈출 직후에도 Ex-Slave/Escaped Slave·Looks like a Slave 상태가 남아 친노예 세력에게 재체포될 수 있다.</strong> 며칠 숨어 외형·옷을 바꾸거나 Grey의 관련 대화로 신분을 해소하는 경로가 있다. <strong>[미확인] 정확한 모든 신분 타이머와 보편적인 모집 능력 상한은 확정하지 않는다.</strong> Slavery의 &#39;Strength+Dexterity+Toughness 75&#39; 설명은 기존 조사에서 다른 모집 자격 문서와 충돌한 항목이다. [S-KEN-REF-04, S-KEN-REF-01]</p><h2 id="_9-이벤트-내러티브" tabindex="-1">9. 이벤트/내러티브 <a class="header-anchor" href="#_9-이벤트-내러티브" aria-label="Permalink to &quot;9. 이벤트/내러티브&quot;">​</a></h2><h3 id="_9-1-사건이-목표를-만드는-방식" tabindex="-1">9.1 사건이 목표를 만드는 방식 <a class="header-anchor" href="#_9-1-사건이-목표를-만드는-방식" aria-label="Permalink to &quot;9.1 사건이 목표를 만드는 방식&quot;">​</a></h3><p><strong>[문서] 공식 설명은 포획·노예화·식인종에게 먹히는 일을 정해진 메인 스토리보다 진행 중 세계의 상호작용으로 제시한다.</strong> 그러나 모든 사건이 완전히 자유 생성되는 것은 아니다. 세력 방문·보복은 대사·위치·관계·지도자 상태 같은 정해진 조건을 가지며, 중요 인물과 유적·책은 고정된 세계사 정보를 제공한다. [S-KEN-REF-02, S-KEN-REF-01, S-KEN-REF-14]</p><p><strong>[추론] 사건의 연쇄는 <code>부상 -&gt; 납치 -&gt; 생존자의 돈벌이 -&gt; 경호 고용 -&gt; 구출 -&gt; 도망 노예 은닉 -&gt; 노예상과 적대</code>처럼 플레이어가 이전에 정하지 않았던 목적을 만든다.</strong> 기존 구조 보고서의 PC Gamer 리뷰 요약은 실제 리뷰어의 비슷한 구출 경험을 기록하지만 이번에는 CSS 덤프에서 원문을 다시 확인하지 않았으므로 직접 관찰 사례로 승격하지 않는다. [S-KEN-REF-01]</p><h3 id="_9-2-방문과-보복은-별도-규칙이다" tabindex="-1">9.2 방문과 보복은 별도 규칙이다 <a class="header-anchor" href="#_9-2-방문과-보복은-별도-규칙이다" aria-label="Permalink to &quot;9.2 방문과 보복은 별도 규칙이다&quot;">​</a></h3><table tabindex="0"><thead><tr><th>사건 유형</th><th>조건·요구 [문서]</th><th>결과</th></tr></thead><tbody><tr><td>Tax Man Visit</td><td>UC 영향권 야외 기지, 세금 3,000c</td><td>거절·무시에 후속 강제집행</td></tr><tr><td>Tribute Round</td><td>Shek 영향권, 식량 조공</td><td>식량 재고와 관계를 함께 소모</td></tr><tr><td>Prayer Day</td><td>HN 영향권, 기도·종교적 인물 조건</td><td>부적합 대응·거부 시 종교적 적대</td></tr><tr><td>지도자 구출·복수</td><td>중요 인물 납치·살해와 세력 조건</td><td>더 강한 보복·구출대; 반복될 수 있음</td></tr><tr><td>순회 부대 습격</td><td>주변에 스폰한 적이 기지를 발견</td><td>예약 이벤트 타이머가 없어도 공격 가능</td></tr></tbody></table><p>근거: S-KEN-REF-01, S-KEN-REF-14. 모든 방문의 주기·최대 인원·재발 횟수가 같다는 뜻은 아니다.</p><h3 id="_9-3-slave-capture의-구체적-규모" tabindex="-1">9.3 Slave Capture의 구체적 규모 <a class="header-anchor" href="#_9-3-slave-capture의-구체적-규모" aria-label="Permalink to &quot;9.3 Slave Capture의 구체적 규모&quot;">​</a></h3><p><strong>[문서] Slave Capture는 대화로 Escaped Slave/Slave Escapee를 모집하거나, 방문한 UC 병사가 Ex-Slave/Escaped Slave 인물을 발견할 때 발동할 수 있다.</strong> &#39;노예를 하나 풀 때마다 무조건 기지 공격&#39;이라는 전역 규칙은 아니다. [S-KEN-REF-06]</p><ul><li><strong>[문서] 공격 규모:</strong> 1-2개 분대, 각 분대는 Slaver Caravan Guards 7-14명, Heavy Guard 0-1명, Caravan Boss가 지휘한다. [S-KEN-REF-06]</li><li><strong>[문서] 도착 후:</strong> 지휘관이 발언하고 인물·문을 공격하며, 쓰러진 인물을 납치해 노예 수용소로 데려간다. [S-KEN-REF-06]</li><li><strong>[추론] 결과:</strong> 한 명을 해방한 도덕적·경제적 선택이 기지 전체의 수비·구출 문제로 확장된다. 사수만 배치하고 성문 안 부상자를 방치하면 공격을 격퇴해도 인력을 잃을 수 있다. [S-KEN-REF-06]</li></ul><h3 id="_9-4-철창과-포식-기둥의-시간차" tabindex="-1">9.4 철창과 포식 기둥의 시간차 <a class="header-anchor" href="#_9-4-철창과-포식-기둥의-시간차" aria-label="Permalink to &quot;9.4 철창과 포식 기둥의 시간차&quot;">​</a></h3><p><strong>[문서] Prisoner Pole은 Cannibals/Fogmen/Gurglers/Southern Hive와 Rebirth 등에서 사용되는 구속 장치다.</strong> 포식 세력에게 묶이면 살아 있는 상태에서 먹히며 몇 초에서 몇 분 사이 탈출·구조할 여지가 있을 수 있다. 모든 기둥 사용자가 식인한다는 뜻은 아니다. 포식은 베기와 UI에 드러나지 않는 음수 bandaged health 손상을 만들 수 있어 로봇 팔다리를 끼웠어도 추가 처치가 필요하다. [S-KEN-REF-06]</p><p><strong>[추론] 납치는 즉시 삭제가 아니라 구조할 수 있는 위치·시간을 가진 위기다.</strong> 다만 &#39;플레이가 계속된다&#39;는 &#39;안전한 패배&#39;가 아니다. 식인·포식·출혈은 타이머를 만들고, 노예 노동은 부상·족쇄·발각 위험을 가진 탈출 퍼즐을 만든다. [문서 근거: S-KEN-REF-04, S-KEN-REF-06, S-KEN-REF-07]</p><h2 id="_10-난이도-압박" tabindex="-1">10. 난이도/압박 <a class="header-anchor" href="#_10-난이도-압박" aria-label="Permalink to &quot;10. 난이도/압박&quot;">​</a></h2><h3 id="_10-1-압박이-결합되는-지점" tabindex="-1">10.1 압박이 결합되는 지점 <a class="header-anchor" href="#_10-1-압박이-결합되는-지점" aria-label="Permalink to &quot;10.1 압박이 결합되는 지점&quot;">​</a></h3><table tabindex="0"><thead><tr><th>압박</th><th>직접 효과 [문서]</th><th>증폭 고리 [추론]</th></tr></thead><tbody><tr><td>굶주림</td><td>200 미만 능력 저하, 심하면 실신·죽음</td><td>힘·운반·생계 약화 -&gt; 다음 음식 구입 지연</td></tr><tr><td>다리·팔 부상</td><td>이동·무기 사용·작업 저하</td><td>도주 실패 -&gt; 재피격 -&gt; 구조자와 치료품 추가 소모</td></tr><tr><td>과적</td><td>도주·전투 속도·회피 불리</td><td>비싼 전리품을 더 들수록 생환 확률 감소</td></tr><tr><td>인원 증가</td><td>전투·노동·구조 능력과 식량 수요 증가</td><td>미숙련 인원만 늘면 소비가 생산보다 먼저 증가</td></tr><tr><td>정착</td><td>생산·저장 가능, 세금·기도·조공·방어 노출</td><td>노동자를 수비에 보내면 생산·치료·판매가 지연</td></tr><tr><td>정치 개입</td><td>관계·도시·순찰 변화</td><td>현상금 수입을 얻는 동시에 판로·안전 지역 상실</td></tr><tr><td>기계화</td><td>고급 의지·빠른 기계 수리</td><td>마모·수리침대 비용·HN 접근 제한</td></tr><tr><td>환경</td><td>산성비·가스·광선·폭풍</td><td>전투 전부터 부상·능력 저하·전력 부족 발생</td></tr></tbody></table><p>근거: S-KEN-REF-01, S-KEN-REF-07, S-KEN-REF-10, S-KEN-REF-11, S-KEN-REF-14, S-KEN-REF-15, S-KEN-REF-17.</p><h3 id="_10-2-성장해도-없어지지-않는-위험" tabindex="-1">10.2 성장해도 없어지지 않는 위험 <a class="header-anchor" href="#_10-2-성장해도-없어지지-않는-위험" aria-label="Permalink to &quot;10.2 성장해도 없어지지 않는 위험&quot;">​</a></h3><p><strong>[문서] Strength는 허기 200 아래 1당 약 0.9%, Dexterity는 약 0.2% 저하되며 허기 100에서 각각 최대 -90%/-20%로 설명된다.</strong> 높은 전투 능력도 영양실조와 부상 때문에 무기 필요 Strength를 못 채우게 될 수 있다. 무기·갑옷·로봇 의지의 좋은 보정이 식량·피·도주로를 대체하지 않는다. [S-KEN-REF-11]</p><p><strong>[추론] 초반에는 &#39;살아 돌아올 것인가&#39;, 중반에는 &#39;무엇을 포기하고 운반할 것인가&#39;, 후반에는 &#39;생산·전투·세계 변화를 동시에 감당할 것인가&#39;가 압박의 중심이다.</strong> 시스템을 익히면 채광·도둑질·훈련을 반복해 자산을 쉽게 늘리는 경로도 있지만, 이를 모든 플레이어에게 재미있거나 모든 지역에서 안전한 경로라고 일반화하지 않는다. 기존 리뷰 요약은 반복 채광·이동·재배의 지루함도 기록한다. [문서 근거: S-KEN-REF-01]</p><h3 id="_10-3-설정과-버그를-기본-규칙에서-분리" tabindex="-1">10.3 설정과 버그를 기본 규칙에서 분리 <a class="header-anchor" href="#_10-3-설정과-버그를-기본-규칙에서-분리" aria-label="Permalink to &quot;10.3 설정과 버그를 기본 규칙에서 분리&quot;">​</a></h3><p><strong>[문서] 절단 빈도 Never/Rare/Frequent는 패배 결과를 바꾸고, 시작 인원 중 일부는 Squad Size Multiplier 영향을 받는다.</strong> 다른 전투·인구·생산·허기 설정이나 모드를 바꾼 결과를 기본값 수치표와 섞지 않는다. <strong>[미확인] 이번에는 모든 게임 옵션의 기본값·범위·인포박스 반영 방식을 재검증하지 않았다.</strong> [S-KEN-REF-01, S-KEN-REF-16]</p><p><strong>[문서] 위키 Bounty의 Bugs에는 철창 부족·수령인의 운반 불가·재인도로 관계/현상금을 반복 획득하는 악용 사례가 있고, 로봇 의지 재장착·저장 불러오기 회복 관련 버그도 기술되어 있다.</strong> 이 문서는 그것을 안정적인 경제 수입·정식 치료 설계로 채택하지 않는다. 세이브·모드·버전별 차이도 있으므로 버그를 규칙의 증거로 사용하지 않는다. [S-KEN-REF-05, S-KEN-REF-07]</p><h3 id="_10-4-충돌·미확인-목록과-적용-경계" tabindex="-1">10.4 충돌·미확인 목록과 적용 경계 <a class="header-anchor" href="#_10-4-충돌·미확인-목록과-적용-경계" aria-label="Permalink to &quot;10.4 충돌·미확인 목록과 적용 경계&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>확인된 사실과 이 문서의 처리</th></tr></thead><tbody><tr><td>Combat/Stats/Research 제목</td><td>Combat/Stats API는 missingtitle. Research는 기존 조사에서 부재가 확인되어 Technology 사용. 실패 응답은 전투 근거가 아님 [S-KEN-REF-14]</td></tr><tr><td>허기 실신·KO 공식 부호</td><td>Health 가이드의 <code>100-KO Point</code>, 양수 KO 설명과 Toughness의 음수 KO 식이 충돌. 음수 KO Point 자체는 Toughness 식으로 제시하되 보편적 허기 실신 경계는 미확인 [S-KEN-REF-07, S-KEN-REF-11]</td></tr><tr><td>최대/최소 방어 확률</td><td>70% 기준·차이별 계수·95% 상한은 문서화. 낮은 구간의 클램프·엔진 전체 동작은 미확인 [S-KEN-REF-11]</td></tr><tr><td>원피해와 사격 방어층</td><td>갑옷 처리 모델은 제시. 모든 무기 원피해·애니메이션 계수·복수 Harpoon 층 처리는 미확인 [S-KEN-REF-11, S-KEN-REF-16]</td></tr><tr><td>노예 모집 상한</td><td>Slavery의 능력 합 75는 기존 모집 조사와 충돌. 강한 포로도 모두 모집 가능하다는 보장 금지 [S-KEN-REF-01, S-KEN-REF-04]</td></tr><tr><td>Town Override 자산</td><td>기존 보고서의 내부 자산 손실 경고와 Town Overrides의 구매 건물 보존 설명 충돌. 건물/실내/재고별 미확인 [S-KEN-REF-01, S-KEN-REF-14]</td></tr><tr><td>먼지폭풍 지각 감소</td><td>능력 설명 20%와 Weather Effects 33.5% 충돌. 정확 상한 미확인 [S-KEN-REF-11, S-KEN-REF-15]</td></tr><tr><td>소형 풍력 최소 풍속</td><td>Wind Generator 표 0.89mph, Small Wind Generator 본문 1.12mph. 최대 25만 채택 [S-KEN-REF-10]</td></tr><tr><td>Dexterity 양팔 보정</td><td>Dexterity 문서의 &#39;+55%&#39; 서술 대신 실제 곱셈 1.25²=1.5625를 계산 예시로 명시 [S-KEN-REF-11, S-KEN-REF-17]</td></tr><tr><td>인물 수·동료 급료</td><td>기본 직접 조종 상한 30과 기간제 NPC 경호는 구분. 서로 다른 경호 일당은 미채택 [S-KEN-REF-01]</td></tr><tr><td>4X식 세계 시뮬레이션</td><td>대규모 변화는 중요 인물 조건·준비된 도시 교체·스폰 중심. NPC 국가들이 모든 생산·정복을 자율 계산한다는 근거 없음 [S-KEN-REF-14]</td></tr><tr><td>실행 검증</td><td>커뮤니티 문서 검토이며 직접 게임 실행·현행 FCS 대조는 없음. 수식은 검증된 프로그램 명세가 아님</td></tr></tbody></table><h3 id="_10-5-출처-안내" tabindex="-1">10.5 출처 안내 <a class="header-anchor" href="#_10-5-출처-안내" aria-label="Permalink to &quot;10.5 출처 안내&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>읽은 자료와 용도</th></tr></thead><tbody><tr><td>S-KEN-REF-01</td><td>기존 <code>내부 종합 조사 문서</code>의 K-시스템 부분: 13시작·생존·정착 3상태·유랑경제·방문·출처 충돌</td></tr><tr><td>S-KEN-REF-02</td><td><code>내부 원문 덤프/steam.txt</code>: 공식 제품·플레이 구조·무레벨스케일링</td></tr><tr><td>S-KEN-REF-03</td><td><code>내부 원문 덤프/wiki-faction.txt</code>: 세력·관계 임계·가입의 적대 변화</td></tr><tr><td>S-KEN-REF-04</td><td><code>capture-k-slavery.txt</code>: 판매·구매·포획·노동·탈출·모집 한계</td></tr><tr><td>S-KEN-REF-05</td><td><code>capture-k-bounty.txt</code>: 범죄 수치·복역·보석·현상범·관계·버그</td></tr><tr><td>S-KEN-REF-06</td><td><code>capture-k-slave-capture.txt</code>, <code>capture-k-prisoner-pole.txt</code>: 탈출 노예 추격 사건·포식 구속</td></tr><tr><td>S-KEN-REF-07</td><td><code>내부 원문 덤프/Guide to Health.txt</code>: 음식 공유·허기 배율·치료·부목·회복</td></tr><tr><td>S-KEN-REF-08</td><td><code>내부 원문 덤프/Food.txt</code>: 음식 영양·가격·적재·식용 종족</td></tr><tr><td>S-KEN-REF-09</td><td><code>내부 원문 덤프/Statistics.txt</code>: 33능력·역할·종족 XP</td></tr><tr><td>S-KEN-REF-10</td><td><code>production-bundle.txt</code>, <code>Tech Level (Tech).txt</code>, <code>Small Shack.txt</code>, <code>Storm House.txt</code>: 연구·농업·전력·산업·건축</td></tr><tr><td>S-KEN-REF-11</td><td><code>combat-bundle.txt</code>: Strength/Toughness/Dexterity·공격/방어/회피·속도·갑옷·성장 모델</td></tr><tr><td>S-KEN-REF-12</td><td><code>skills-bundle.txt</code>의 열람 구간: 운동·절도·해정·기절·엔지니어·제작</td></tr><tr><td>S-KEN-REF-13</td><td><code>Jobs.txt</code>: 작업 우선순위·자동 운반·의료 예외</td></tr><tr><td>S-KEN-REF-14</td><td>이번 API Technology/World States, 기존 Town Overrides; API 실패 기록 포함</td></tr><tr><td>S-KEN-REF-15</td><td><code>Weather Effects.txt</code>: 산성비·광선·먼지폭풍·가스</td></tr><tr><td>S-KEN-REF-16</td><td><code>Damage.txt</code>: 부위·피해·마모·절단·관통의 문서 모델</td></tr><tr><td>S-KEN-REF-17</td><td><code>Robot Limbs.txt</code>의 열람 구간: 절단·수리·Masterwork 의지·HN 접근</td></tr><tr><td>S-KEN-REF-18</td><td><code>Crossbows.txt</code>, <code>Precision Shooting.txt</code>: 석궁 운용·볼트·오사</td></tr></tbody></table><p><strong>[추론] K-시스템의 중심은 &#39;강한 한 명&#39;이나 &#39;완성된 도시&#39;가 아니라, 손실을 견디며 다음 행동을 고를 수 있는 집단이다.</strong> 돈·신체·기술·운반·연구·관계가 서로를 대체하지 않고 연결되므로, 생존에서 후기 정치 개입까지 같은 루프가 규모와 결과를 바꾸며 이어진다.</p>`,176)])])}const E=d(n,[["render",s]]);export{c as __pageData,E as default};
